        [$kw['anchor'] ?? null, array_map(fn ($m) => mb_substr((string) $kw['detail'], $m[0], $m[1] - $m[0]), (array) ($kw['marks'] ?? []))]);
    check('search guides page: a query ≤ 2 ms (warm, ' . round($r['ms'], 2) . ')', $r['ms'] <= 2, (string) $r['ms']);
    // the jump
