        try {
            drillSet($bad);
            check('drill settings: refused ' . json_encode($bad), false);
        } catch (Problem) {
            check('drill settings: refused ' . json_encode($bad), true);
        }
    }

    // ---- out of room (nostromo 2026-10-08, reproduced on Tower): the play's and the server's own words, df inside the
    //      throwaway, a kill for memory — «not checked» with its sizes, never «failed»; any other failure stays the play's
    $nr = "$tmp/noroom";
    @mkdir($nr, 0700, true);
    file_put_contents("$tmp/docker-noroom", "#!/bin/sh\nD=" . escapeshellarg($nr) . "\necho \"\$*\" >>\"\$D/calls\"\ncase \"\$1\" in\n"
        . "  logs) cat \"\$D/logs\" ;;\n"
        . "  exec) [ -f \"\$D/df\" ] || { echo 'Error response from daemon: container is not running' >&2; exit 1; }; cat \"\$D/df\" ;;\n"
        . "  inspect) cat \"\$D/oom\" ;;\nesac\nexit 0\n");
    chmod("$tmp/docker-noroom", 0755);
    $GLOBALS['drill']['docker'] = "$tmp/docker-noroom";
    $nrOut = ['level' => 0, 'copy' => 'snapshot', 'run' => '20261101-0200', 'params' => ['container' => 'immich_postgres'], 'seconds' => 9];
    $nrStep = ['container' => 'immich_postgres', 'need' => 1806 << 20, 'mem' => 1806 << 20, 'datadir' => '/var/lib/postgresql/data'];
    $room = function (string $said, string $logs, ?string $df, bool $oom = false, string $state = 'failed') use ($nr, $fix, $nrOut, $nrStep): ?array {
        copy("$fix/$logs", "$nr/logs");
        $df === null ? @unlink("$nr/df") : copy("$fix/$df", "$nr/df");
        file_put_contents("$nr/oom", $oom ? "true\n" : "false\n");
        $said = is_file("$fix/$said") ? (string) file_get_contents("$fix/$said") : $said;
        return drillPlayRoom(['state' => $state, 'note' => 'play_failed', 'detail' => ''], DRILL_PREFIX . '20261101-041200-ab12-3', $nrStep, $said, $nrOut);
    };
    $r = $room('no-room-postgres-play.txt', 'no-room-postgres-server.txt', null);
    same('drill no room: Postgres\' PANIC on its WAL, the connection lost, the throwaway gone — not checked, its sizes, the dump intact (L1)',
        ['not_checked', 'dump_no_room', 1, ['container' => 'immich_postgres', 'need_mb' => 1806, 'ram_mb' => 1806], 9, 'snapshot'],
        [$r['state'] ?? null, $r['code'] ?? null, $r['level'] ?? null, $r['params'] ?? null, $r['seconds'] ?? null, $r['copy'] ?? null]);
    same('drill no room: psql going on after «could not extend file» (the play only «with errors») — not checked too', ['not_checked', 'dump_no_room'],
        array_values(array_intersect_key($room('no-room-postgres-extend.txt', 'server-quiet.txt', 'df-room.txt', false, 'warning') ?? [], ['state' => 1, 'code' => 1])));
    same('drill no room: MariaDB\'s «The table … is full»', ['not_checked', 'dump_no_room'],
        array_values(array_intersect_key($room('no-room-mariadb-play.txt', 'server-quiet.txt', 'df-room.txt') ?? [], ['state' => 1, 'code' => 1])));
    same('drill no room: only «connection to server was lost» — the server\'s own log says ENOSPC, its tmpfs full (df), or it was killed for memory',
        ['dump_no_room', 'dump_no_room', 'dump_no_room'], [
            $room("connection to server was lost\n", 'no-room-postgres-server.txt', null)['code'] ?? null,
            $room("connection to server was lost\n", 'server-quiet.txt', 'df-full.txt')['code'] ?? null,
            $room("connection to server was lost\n", 'server-quiet.txt', null, true)['code'] ?? null]);
    same('drill no room: a lost connection with room left and no kill, another error, a play that went through — the play\'s own result (failed stays failed)',
        [null, null, null], [$room("connection to server was lost\n", 'server-quiet.txt', 'df-room.txt'), $room('play-other-error.txt', 'server-quiet.txt', 'df-room.txt'),
                             $room('', 'no-room-postgres-server.txt', 'df-full.txt', false, 'ok')]);
    check('drill no room: df looks at the throwaway\'s data dir only', str_contains((string) file_get_contents("$nr/calls"), 'exec ' . DRILL_PREFIX . '20261101-041200-ab12-3 df -P -k /var/lib/postgresql/data'));
    file_put_contents("$tmp/play.log", str_repeat('x', 70000) . "PANIC: No space left on device\n");
    same('drill no room: the log since the play began, its end only', [true, 65536], [str_ends_with(drillLogSince("$tmp/play.log", 10), "device\n"), strlen(drillLogSince("$tmp/play.log", 10))]);
    same('drill no room: nothing written since', '', drillLogSince("$tmp/play.log", (int) filesize("$tmp/play.log")));
    unset($GLOBALS['drill']['docker']);

    // ---- a docker stand-in: containers in a file ("name label"), every call logged
    $dock = "$tmp/docker";
    file_put_contents("$tmp/containers", '');
    file_put_contents($dock, "#!/bin/sh\n" . 'echo "$*" >>' . escapeshellarg("$tmp/docker.log") . "\n"
        . 'C=' . escapeshellarg("$tmp/containers") . '; K=' . escapeshellarg("$tmp/kopia") . "\n"
        . 'for a in "$@"; do last="$a"; done' . "\n"
        . 'case "$1" in' . "\n"
        . '  ps) cut -d" " -f1 "$C" ;;' . "\n"
        . '  inspect) grep -q "^$last " "$C" || exit 1; grep "^$last " "$C" | cut -d" " -f2 ;;' . "\n"
        . '  rm) grep -v "^$last " "$C" >"$C.t"; mv "$C.t" "$C" ;;' . "\n"
        . '  exec) prev=""; obj=""; list=""; for a in "$@"; do [ "$prev" = show ] && obj="$a"; [ "$prev" = list ] && list=1; prev="$a"; done' . "\n"
        . '        if [ -n "$obj" ]; then cat "$K/$obj" 2>/dev/null || exit 1; elif [ -n "$list" ]; then cat "$K/list.json"; fi ;;' . "\n"
        . "esac\nexit 0\n");
    chmod($dock, 0755);
    $GLOBALS['drill']['docker'] = $dock;

    // ---- the journal and the sweeper
    $a = '20261101-030000-aaaa';
    $b = '20261101-040000-bbbb';
    rsPrivateDir("$tmp/data/restore-drill");
    foreach ([$a, $b] as $jid) {
        rsPrivateDir(drillDir($jid));
    }
    $ja = drillJournalNew($a, ['scope' => 'monthly', 'deadline' => $now, 'steps' => [['do' => 'dump', 'kind' => 'app', 'id' => 'x', 'name' => 'x']]]);
    $ja['result'] = 'running';
    $ja['pid'] = 4194305;                  // gone
    $ja['made'] = [['kind' => 'container', 'name' => DRILL_PREFIX . "$a-0", 'gone' => false, 't' => 1]];
    drillJournalWrite($ja, false);
    file_put_contents("$tmp/containers", implode("\n", [
        DRILL_PREFIX . "$a-0 $a",                                   // the interrupted drill's own
        DRILL_PREFIX . '20261020-030000-cccc-1 20261020-030000-cccc', // an orphan without a journal, all three marks match
        DRILL_PREFIX . '20261020-030000-dddd-1 someone-else',        // the label names another: not ours
        'immich_postgres 20261020-030000-eeee',                      // not a drill's name
        DRILL_PREFIX . "$b-2 $b",                                    // the drill going on now
    ]) . "\n");
    $removed = drillSweep($b, true);
    sort($removed);
    same('drill sweeper: the interrupted drill\'s throwaway and an orphan whose name, label and id say it is a drill\'s — never anything else, never the drill going on',
        [DRILL_PREFIX . '20261020-030000-cccc-1', DRILL_PREFIX . "$a-0"], $removed);
    same('drill sweeper: what stays', ['uso-drill-20261020-030000-dddd-1', 'immich_postgres', "uso-drill-$b-2"],
        array_map(fn ($l) => explode(' ', $l)[0], array_values(array_filter(explode("\n", (string) file_get_contents("$tmp/containers"))))));
    $after = drillJournal($a);
    same('drill sweeper: the journal says interrupted, its throwaway gone', ['interrupted', true], [$after['result'] ?? null, $after['made'][0]['gone'] ?? null]);
    same('drill sweeper: the job file of the page untouched by an old journal', false, is_file("$tmp/data/restore-drill-job.json"));
    file_put_contents("$tmp/docker.log", '');
    drillSweep(null, false);
    same('drill sweeper: hourly with every journal closed — no docker call', '', (string) file_get_contents("$tmp/docker.log"));
    // the record for the night watchman: written before each create, root only, newest 50 within 7 days
    $jr = drillJournalNew($b, ['scope' => 'now', 'deadline' => $now, 'steps' => []]);
    for ($i = 0; $i < 55; $i++) {
        drillMade($jr, ['kind' => 'container', 'name' => DRILL_PREFIX . "$b-$i", 'image' => 'sha256:' . str_repeat('b', 64)]);
    }
    $rec = readJson("$tmp/data/restore-drill/record.json");
    same('drill record: the newest 50, in the watchman\'s shape, root only', [50, DRILL_PREFIX . "$b-54", ['t', 'kind', 'name', 'image', 'id'], '0600'],
        [count($rec['made'] ?? []), end($rec['made'])['name'] ?? null, array_keys($rec['made'][0] ?? []), substr(sprintf('%o', fileperms("$tmp/data/restore-drill/record.json")), -4)]);
    same('drill journal: «made» written before the create', DRILL_PREFIX . "$b-0", drillJournal($b)['made'][0]['name'] ?? null);

    // ---- what a drill left, for Ms. Dustdevil: the sweeper's own look (journals of drills whose job is gone; containers
    //      no journal names only when name, label, id AND the drill's record agree) and its own removal, by her ids
    $lc = '20261102-030000-c0c0';
    rsPrivateDir(drillDir($lc));
    $lram = drillRamFile($lc, 2, 'db/pg.sql.gz');
    file_put_contents($lram, 'x');
    $jl = drillJournalNew($lc, ['scope' => 'monthly', 'deadline' => $now, 'steps' => []]);
    $jl['result'] = 'running';
    $jl['pid'] = 4194305;                  // gone
    $jl['made'] = [['kind' => 'container', 'name' => DRILL_PREFIX . "$lc-1", 'gone' => false, 't' => 5],
                   ['kind' => 'container', 'name' => DRILL_PREFIX . "$lc-3", 'gone' => false, 't' => 6],          // not there any more
                   ['kind' => 'kopia_tmp', 'name' => "/tmp/uso-drill-$lc", 'container' => 'kopia', 'uid' => 0, 'gone' => false, 't' => 7],
                   ['kind' => 'kopia_dump', 'name' => $lram, 'gone' => false, 't' => 8]];
    drillJournalWrite($jl, false);
    $recFile = "$tmp/data/restore-drill/record.json";
    $recKeep = (string) file_get_contents($recFile);
    drillRecord(['t' => time(), 'kind' => 'container', 'name' => DRILL_PREFIX . '20261021-030000-dada-1', 'image' => 'sha256:' . str_repeat('d', 64), 'id' => '20261021-030000-dada']);
    file_put_contents("$tmp/containers", implode("\n", [
        DRILL_PREFIX . "$lc-1 $lc",                                       // the interrupted drill's own
        DRILL_PREFIX . '20261021-030000-dada-1 20261021-030000-dada',     // no journal, but the record names it
        DRILL_PREFIX . '20261021-030000-fafa-1 20261021-030000-fafa',     // a label and a name — no record: not listed
        DRILL_PREFIX . "$b-7 $b",                                         // the drill going on now
    ]) . "\n");
    $certBefore = @file_get_contents($GLOBALS['drill']['cert']);
    $sorted = function (array $x): array { sort($x); return $x; };
    $left = drillLeftovers();
    same('drill leftovers: what the interrupted drill\'s journal names and is there, and a container the record names — never a label alone, never the drill going on',
        $sorted(["drill:$lc:$lram", "drill:$lc:/tmp/uso-drill-$lc", "drill:$lc:" . DRILL_PREFIX . "$lc-1", 'drill:20261021-030000-dada:' . DRILL_PREFIX . '20261021-030000-dada-1']),
        $sorted(array_column($left, 'id')));
    same('drill leftovers: what each is', ['container', 'kopia_tmp', 'kopia_dump'], array_values(array_unique(array_column($left, 'what'))));
    $ent = clDrillEntries($left);
    same('drill leftovers in Ms. Dustdevil\'s Docker room: category «drill», removable rows', [['drill'], ['drill'], 4], [array_values(array_unique(array_column($ent, 'category'))),
        array_values(array_unique(array_column($ent, 'kind'))), count(array_filter($ent, fn ($e) => $e['why'] === null && !$e['force']))]);
    file_put_contents("$tmp/docker.log", '');
    $gone = drillSweep($b, true, ["drill:$lc:$lram", 'drill:20261021-030000-dada:' . DRILL_PREFIX . '20261021-030000-dada-1']);
    same('drill leftovers removed by her ids, through the sweeper — only those', [$sorted(["drill:$lc:$lram", 'drill:20261021-030000-dada:' . DRILL_PREFIX . '20261021-030000-dada-1']), false, true],
        [$sorted($gone), is_file($lram), str_contains((string) file_get_contents("$tmp/containers"), DRILL_PREFIX . "$lc-1 ")]);
    $jl2 = drillJournal($lc);
    same('drill leftovers: the journal says what went, the drill interrupted', ['interrupted', [false, false, false, true]],
        [$jl2['result'] ?? null, array_map(fn ($x) => (bool) $x['gone'], $jl2['made'] ?? [])]);
    same('drill leftovers: the rest still listed', $sorted(["drill:$lc:/tmp/uso-drill-$lc", "drill:$lc:" . DRILL_PREFIX . "$lc-1"]), $sorted(array_column(drillLeftovers(), 'id')));
    drillSweep($b, true, ["drill:$lc:/tmp/uso-drill-$lc", "drill:$lc:" . DRILL_PREFIX . "$lc-1"]);
    same('drill leftovers: all gone — nothing listed; the unrecorded one stays for the deep sweep at the agent\'s start', [[], true],
        [drillLeftovers(), str_contains((string) file_get_contents("$tmp/containers"), DRILL_PREFIX . '20261021-030000-fafa-1 ')]);
    file_put_contents($recFile, $recKeep);
    $certBefore === false ? @unlink($GLOBALS['drill']['cert']) : file_put_contents($GLOBALS['drill']['cert'], $certBefore);      // the interruption's history row: not the certificate tests'

    // ---- quick on her every scan, deep when asked and once an hour (review 2026-10-09): a drill folder of its own
    $dataKeep = $GLOBALS['drill']['data'];
    $jobKeep = $GLOBALS['drill']['job_file'];
    $GLOBALS['drill']['data'] = "$tmp/data/drill-quick";
    $GLOBALS['drill']['job_file'] = "$tmp/data/drill-quick-job.json";
    rsPrivateDir(drillData());
    unset($GLOBALS['drillLeftDeep']);
    $dlog = function (): bool { $l = (string) file_get_contents($GLOBALS['tmpDrillLog']); file_put_contents($GLOBALS['tmpDrillLog'], ''); return str_contains($l, 'label=' . DRILL_LABEL); };
    $GLOBALS['tmpDrillLog'] = "$tmp/docker.log";
    file_put_contents("$tmp/containers", '');
    file_put_contents("$tmp/docker.log", '');
    $q = [];
    drillLeftovers(false);
    $q[] = $dlog();                                       // the first look: deep
    drillLeftovers(false);
    $q[] = $dlog();                                       // quick, nothing open: no Docker
    $wk = date('Ymd-His', time() - 2 * 86400) . '-a1a1';    // last week's, closed: its throwaway gone, the record names it
    rsPrivateDir(drillDir($wk));
    $jw = drillJournalNew($wk, ['scope' => 'monthly', 'deadline' => $now, 'steps' => []]);
    $jw['result'] = 'passed';
    $jw['made'] = [['kind' => 'container', 'name' => DRILL_PREFIX . "$wk-1", 'gone' => true, 't' => 5]];
    drillJournalWrite($jw, false);
    drillRecord(['t' => time(), 'kind' => 'container', 'name' => DRILL_PREFIX . "$wk-1", 'image' => 'sha256:' . str_repeat('a', 64), 'id' => $wk]);
    drillLeftovers(false);
    $q[] = $dlog();                                       // a closed drill the record names: still no Docker
    $nj = date('Ymd-His', time() - 3600) . '-b2b2';         // the record names one whose journal isn't there
    drillRecord(['t' => time(), 'kind' => 'container', 'name' => DRILL_PREFIX . "$nj-1", 'image' => 'sha256:' . str_repeat('b', 64), 'id' => $nj]);
    file_put_contents("$tmp/containers", DRILL_PREFIX . "$nj-1 $nj\n");
    $q[] = array_column(drillLeftovers(false), 'id');      // Docker asked: listed
    $q[] = $dlog();
    file_put_contents("$tmp/containers", '');
    @unlink(drillData() . '/record.json');
    drillRecord(['t' => time(), 'kind' => 'container', 'name' => DRILL_PREFIX . "$wk-1", 'image' => 'sha256:' . str_repeat('a', 64), 'id' => $wk]);
    drillLeftovers(true);
    $q[] = $dlog();                                       // «Look again»: deep
    $old = '20250101-030000-c3c3';                         // older than a week, its throwaway still there
    rsPrivateDir(drillDir($old));
    $jo = drillJournalNew($old, ['scope' => 'monthly', 'deadline' => $now, 'steps' => []]);
    $jo['result'] = 'interrupted';
    $jo['made'] = [['kind' => 'container', 'name' => DRILL_PREFIX . "$old-1", 'gone' => false, 't' => 5]];
    drillJournalWrite($jo, false);
    file_put_contents("$tmp/containers", DRILL_PREFIX . "$old-1 $old\n");
    $q[] = [drillLeftovers(false), $dlog()];               // quick: the old journal isn't read, no Docker
    $GLOBALS['drillLeftDeep']['at'] = time() - DRILL_LEFT_DEEP - 1;
    $q[] = [array_column(drillLeftovers(false), 'id'), $dlog()];     // an hour on: deep — the old one found
    $q[] = [array_column(drillLeftovers(false), 'id'), $dlog()];     // quick again: what the deep look listed is looked at, Docker asked
    same('drill leftovers: quick on every scan — no Docker while nothing is open; a closed drill in the record doesn\'t count; a container the record names without a journal does; deep when asked',
        [true, false, false, ['drill:' . $nj . ':' . DRILL_PREFIX . "$nj-1"], true, true], array_slice($q, 0, 6));
    same('drill leftovers: quick reads only the last week (and what the deep look listed); deep once an hour finds the old one, then quick keeps looking at it',
        [[[], false], [['drill:' . $old . ':' . DRILL_PREFIX . "$old-1"], true], [['drill:' . $old . ':' . DRILL_PREFIX . "$old-1"], true]], array_slice($q, 6));
    unset($GLOBALS['drillLeftDeep'], $GLOBALS['tmpDrillLog']);
    $GLOBALS['drill']['data'] = $dataKeep;
    $GLOBALS['drill']['job_file'] = $jobKeep;

    // ---- the certificate: passed = nothing failed (warnings, «not checked» and asleep said, never hidden)
    $step = fn (string $do, string $of, string $name, string $state, int $level, string $copy, ?int $t, array $params = [], string $code = 'x') =>
        ['do' => $do, 'kind' => $of, 'id' => $name, 'name' => $name, 'state' => $state, 'level' => $level, 'copy' => $copy, 'state_time' => $t, 'code' => $code,
         'params' => $params, 'finished' => $now, 'run' => '20261101-0300'];
    $jc = ['id' => $a, 'scope' => 'monthly', 'started' => $now - 600, 'finished' => $now, 'egress' => 4096, 'result' => 'passed', 'reason' => null, 'steps' => [
        $step('package', 'app', 'immich', 'ok', 1, 'package', $now - 3000),
        $step('dump', 'app', 'immich', 'warning', 2, 'snapshot', $now - 3600, ['seconds' => 384], 'extensions_missing'),
        $step('kopia', 'app', 'immich', 'ok', 1, 'kopia', $now - 90000),
        $step('sqlite', 'app', 'EmbyServer', 'not_checked', 0, 'snapshot', null, [], 'sqlite_unchecked'),
        $step('vmdisk', 'vm', 'Win', 'asleep', 0, 'snapshot', null, [], 'asleep'),
        ['do' => 'kopia', 'kind' => 'share', 'id' => 'appdata', 'name' => 'appdata', 'state' => 'skipped'],
    ]];
    $cert = drillCertWrite($jc, ['place' => ['share' => 'UnraidSecretaryOffice']]);
    same('drill certificate: interface 1, the last drill, when it last passed', [1, 'passed', $now, 5, 4096],
        [$cert['interface'] ?? null, $cert['last']['result'] ?? null, $cert['last_passed'] ?? null, $cert['last']['items'] ?? null, $cert['last']['egress'] ?? null]);
    same('drill certificate: counted — proven, warnings, failed, not checked, asleep', [2, 1, 0, 1, 1],
        [$cert['last']['proven'], $cert['last']['warnings'], $cert['last']['failed'], $cert['last']['not_checked'], $cert['last']['asleep']]);
    same('drill certificate: per item kind, level, copy, result, code (a skipped step is no item)', [['dump', 2, 'snapshot', 'warning', 'extensions_missing']],
        array_values(array_map(fn ($it) => [$it['kind'], $it['level'], $it['copy'], $it['result'], $it['code']], array_filter($cert['items'], fn ($it) => $it['kind'] === 'dump'))));
    $lose = array_column($cert['lose'], null, 'id');
    same('drill certificate: what would come back — the oldest proven part locally, Kopia\'s own, how long the dump took', [$now - 3600, $now - 90000, 384, 2],
        [$lose['immich']['local'] ?? null, $lose['immich']['kopia'] ?? null, $lose['immich']['played'] ?? null, $lose['immich']['best'] ?? null]);
    same('drill certificate: the file in exactly that shape for the page (api part «drill»)', $cert, drillCertificate());
    $jf = ['id' => $b, 'result' => 'failed', 'started' => $now, 'finished' => $now + 60] + $jc;
    $jf['steps'][0]['state'] = 'failed';
    $cert = drillCertWrite($jf, null);
    same('drill certificate: a failed drill replaces the items, «last passed» stays', ['failed', $now, 1, [$b, $a]],
        [$cert['last']['result'], $cert['last_passed'], $cert['last']['failed'], array_column($cert['history'], 'id')]);
    $ab = ['id' => '20261102-030000-abab', 'result' => 'aborted', 'reason' => 'array_stopping', 'started' => $now, 'finished' => $now + 5] + $jc;
    $cert = drillCertWrite($ab, null);
    same('drill certificate: an aborted drill joins the history only (what was proven stays)', ['failed', $b, 'aborted', 'array_stopping'],
        [$cert['last']['result'], $cert['last']['id'], $cert['history'][0]['result'], $cert['history'][0]['reason']]);
    // a newer office's certificate (another interface, met after a downgrade): its history goes on as it is, the file aside
    $certFile = $GLOBALS['drill']['cert'];
    $keep = (string) file_get_contents($certFile);
    $later = ['id' => '20271201-030000-ffff', 'result' => 'passed', 'proofs' => ['a' => 1], 'by' => 'a newer office'];
    $newer = json_encode(['interface' => 2, 'proofs' => [], 'history' => [$later, $cert['history'][0]]]);
    file_put_contents($certFile, $newer);
    $cert2 = drillCertWrite($jc, ['place' => ['share' => 'UnraidSecretaryOffice']]);
    same('drill certificate of another interface: written as interface 1, the newer history rows kept as they are, behind this drill\'s',
        [1, [$a, '20271201-030000-ffff', $cert['history'][0]['id']], $later], [$cert2['interface'], array_column($cert2['history'], 'id'), $cert2['history'][1]]);
    same('drill certificate of another interface: the whole file kept aside', $newer, @file_get_contents("$certFile.before-" . AGENT_VERSION));
    @unlink("$certFile.before-" . AGENT_VERSION);
    $c1 = json_decode($keep, true);
    $c1['from_later'] = ['kept' => true];
    file_put_contents($certFile, json_encode($c1));
    same('drill certificate: a key this version doesn\'t know kept through a write', ['kept' => true], drillCertWrite($ab, null)['from_later'] ?? null);
    file_put_contents($certFile, $keep);

    // ---- the Team Lead, the Dashboard, Mr. Backupsy's line, the metrics
    $ok = fn (array $f) => array_map(fn ($x) => [$x['id'], $x['ok']], $f);
    same('drill checks: packages younger than 30 days — no drill asked for yet', [], $ok(drillChecks([], $now - 10 * 86400, $now)));
    same('drill checks: no drill ever, packages 40 days old — recommended, open', [['drill', false]], $ok(drillChecks([], $now - 40 * 86400, $now)));
    $passed = ['interface' => 1, 'last' => ['result' => 'passed', 'ended' => $now - 86400], 'last_passed' => $now - 86400, 'items' => []];
