        file_put_contents($paths['rsyslog_cfg'], implode('', array_map(fn ($k, $x) => "$k=\"$x\"\n", array_keys($over + $v), $over + $v)));
    };
    $checks = fn (array $extra = []) => array_column(watchnetChecks($extra + $o), null, 'id');
    $cfgFile([]);
    file_put_contents("$src/sec.ini", "[\"syslog\"]\nexport=\"-\"\nsecurity=\"public\"\n");
    $c = $checks();
    same('net checks: all well — an own share on an SSD pool, rotation 50 MB × 4, not exported, the port free, no loop',
        ['syslog_no_rotation' => true, 'syslog_port_taken' => true, 'syslog_share_public' => true, 'syslog_share_sleeps' => true],
        (function ($x) { ksort($x); return $x; })(array_map(fn ($f) => $f['ok'], $c)));
    $cfgFile(['server_folder' => '/mnt/user/media']);
    $c = $checks();
    same('net checks: syslog_share_sleeps — a pool whose disks spin down: recommended', ['recommended', false, 'hive'],
        [$c['syslog_share_sleeps']['level'], $c['syslog_share_sleeps']['ok'], $c['syslog_share_sleeps']['params']['disks']]);
    $cfgFile(['server_folder' => '/mnt/user/old']);
    same('net checks: … an array-only share: required', ['required', false], [$checks()['syslog_share_sleeps']['level'], $checks()['syslog_share_sleeps']['ok']]);
    $cfgFile(['log_rotation' => '']);
    same('net checks: syslog_no_rotation (required) — off', ['required', false], [$checks()['syslog_no_rotation']['level'], $checks()['syslog_no_rotation']['ok']]);
    $cfgFile(['log_size' => '900M', 'log_files' => '4']);
    same('net checks: … or more than 2 GB in all', false, $checks()['syslog_no_rotation']['ok']);
    $cfgFile([]);
    file_put_contents("$src/sec.ini", "[\"syslog\"]\nexport=\"e\"\nsecurity=\"public\"\n");
    same('net checks: syslog_share_public — exported over SMB (the files are writable by anyone who writes the share)', [false, 'SMB'],
        [$checks()['syslog_share_public']['ok'], $checks()['syslog_share_public']['params']['proto']]);
    file_put_contents("$src/sec.ini", "[\"syslog\"]\nexport=\"-\"\n");
    $fs = ['Name' => '/firesight', 'Config' => ['Env' => ['SYSLOG_UDP_PORT=514']], 'HostConfig' => ['NetworkMode' => 'host', 'PortBindings' => []]];
    $alloy = ['HostConfig' => ['NetworkMode' => 'bridge', 'PortBindings' => ['514/udp' => [['HostPort' => '514']]]]];
    $c = $checks(['containers' => [['name' => 'firesight', 'image' => 'ghcr.io/tjindarr/unifi-insights-hub:latest'], ['name' => 'Alloy', 'image' => 'grafana/alloy:latest'],
                                    ['name' => 'web', 'image' => 'nginx']],
                  'inspect' => fn (string $n) => $n === 'firesight' ? $fs : ($n === 'Alloy' ? $alloy : null)]);
    same('net checks: syslog_port_taken — the usual holders named by image', [false, 'firesight (FireSight), Alloy (Alloy)'],
        [$c['syslog_port_taken']['ok'], $c['syslog_port_taken']['params']['names']]);
    $cfgFile(['remote_server' => '192.0.2.20']);
    same('net checks: syslog_loop — Remote syslog server is this server (Benj\'s case on 2026-10-08)', ['recommended', false],
        [$checks()['syslog_loop']['level'] ?? null, $checks()['syslog_loop']['ok'] ?? null]);
    $cfgFile(['remote_server' => 'tower']);
    same('net checks: … also by its name', false, $checks()['syslog_loop']['ok'] ?? null);
    $cfgFile(['remote_server' => '192.0.2.99']);
    same('net checks: … another server is fine', true, $checks()['syslog_loop']['ok'] ?? null);
    $cfgFile(['local_server' => '']);
    same('net checks: syslog_off — a hint only when he is hired and the router guide was opened', [[], ['syslog_off']],
        [array_keys(array_filter($checks(['hired' => true]), fn ($f) => $f['id'] === 'syslog_off')),
         array_keys(array_filter($checks(['hired' => true, 'guide' => $now]), fn ($f) => $f['id'] === 'syslog_off'))]);

    // ---- the Consultant's look: which shares qualify, the loop, the senders (only while the folder is awake)
    $cfgFile(['remote_server' => '127.0.0.1']);
    $a = watchnetAdvisor($o);
    same('net advisor: Unraid\'s syslog server as it is — on, its share, where a share `syslog` belongs (the pools that never sleep; the array only all-SSD), the loop',
        [true, 'syslog', ['master'], false, true],
        [$a['on'], $a['share'], $a['pools'], $a['array_ssd'], $a['loop']]);
    // where the share belongs, by disks.ini alone (Benj, 2026-10-08: create a share, don't pick an existing one): nostromo's
    // shape - master (NVMe, delay 0), ripley (six SSDs, the default delay), sulaco (NVMe), the boot pool mother (SSDs, but the
    // Boot slot's device - left out), hive (four HDDs at 15 min), the array of HDDs
    $pf = fn (string $disks, string $delay = '30') => (function () use ($o, $disks, $delay) {
        file_put_contents($o['disks_ini'] . '.x', $disks);
        file_put_contents($o['var_ini'] . '.x', "spindownDelay=\"$delay\"\n");
        $f = watchnetFacts(['disks_ini' => $o['disks_ini'] . '.x', 'var_ini' => $o['var_ini'] . '.x'] + $o);
        return [$f['pools'], $f['array_ssd']];
    })();
    $dk = fn (string $n, string $dev, string $rot, string $delay, string $type = 'Cache', string $fs = '') =>
        "[\"$n\"]\nname=\"$n\"\ndevice=\"$dev\"\nrotational=\"$rot\"\nspundown=\"0\"\ntype=\"$type\"\nspindownDelay=\"$delay\"\n" . ($fs !== '' ? "fsType=\"$fs\"\n" : '');
    $nostromo = $dk('parity', 'sdo', '1', '-1', 'Parity') . $dk('disk1', 'sda', '1', '-1', 'Data', 'luks:btrfs') . $dk('disk2', 'sdq', '1', '-1', 'Data', 'luks:btrfs')
        . $dk('hive', 'sdj', '1', '15', 'Cache', 'zfs') . $dk('hive2', 'sdg', '1', '15') . $dk('master', 'nvme0n1', '0', '0', 'Cache', 'luks:zfs') . $dk('master2', 'nvme1n1', '0', '0')
        . $dk('mother', 'sde', '0', '-1', 'Cache', 'luks:zfs') . $dk('mother2', 'sdm', '0', '-1') . $dk('ripley', 'sdb', '0', '-1', 'Cache', 'luks:zfs') . $dk('ripley2', 'sdf', '0', '-1')
        . $dk('sulaco', 'nvme2n1', '0', '-1', 'Cache', 'luks:zfs') . $dk('flash', 'sde', '0', '-1', 'Boot', 'zfs') . $dk('flash2', 'sdm', '0', '-1', 'Boot');
    same('net advisor: nostromo - master, ripley, sulaco; not mother (the boot pool), not hive (spins down), not the array (HDDs)', [['master', 'ripley', 'sulaco'], false], $pf($nostromo));
    // uso-test: VM disks, all rotational=1 with the default delay - and the default is «Never» (var.ini spindownDelay 0):
    // big and cache never sleep; the array (HDDs by their word) stays out
    $usotest = $dk('disk1', 'sda', '1', '-1', 'Data', 'btrfs') . $dk('disk2', 'sdb', '1', '-1', 'Data', 'zfs') . $dk('big', 'vda', '1', '-1', 'Cache', 'zfs')
        . $dk('cache', 'sdc', '1', '-1', 'Cache', 'zfs') . $dk('cache2', 'sdd', '1', '-1') . $dk('flash', 'sde', '1', '-1', 'Flash', 'vfat');
    same('net advisor: uso-test - big and cache (the default delay is Never), not the array', [['big', 'cache'], false], $pf($usotest, '0'));
    same('net advisor: … with the default at 30 min every pool there spins down - none', [[], false], $pf($usotest));
    same('net advisor: an array of SSDs qualifies too (and a pool of one SSD at the default)', [['nvme'], true],
        $pf($dk('disk1', 'sda', '0', '-1', 'Data', 'xfs') . $dk('disk2', 'sdb', '0', '-1', 'Data', 'xfs') . $dk('nvme', 'nvme0n1', '0', '-1', 'Cache', 'zfs')));
    same('net advisor: … but not an array with one HDD in it', [[], false], $pf($dk('disk1', 'sda', '0', '-1', 'Data', 'xfs') . $dk('disk2', 'sdb', '1', '0', 'Data', 'xfs')));
    foreach (['en', 'de', 'it', 'fr', 'es'] as $lang) {
        $al = json_decode((string) file_get_contents(OFFICE_WEB . "/desks/advisor/lang/$lang.json"), true) ?: [];
        check("net advisor: the guide's step says create a share, its pools and the fallback ($lang)",
            str_contains((string) ($al['net.syslog.3'] ?? ''), '⟦Add Share⟧') && str_contains((string) ($al['net.syslog.3'] ?? ''), '{pools}')
            && str_contains((string) ($al['net.syslog.pools'] ?? ''), '{list}') && isset($al['net.syslog.pools_none'], $al['net.syslog.the_array']) && !isset($al['net.syslog.shares']));
    }
    $cfgFile(['server_folder' => $logs]);
    $a = watchnetAdvisor($o);
    same('net advisor: the senders with a file there, never the loop\'s', ['192.0.2.1', '192.0.2.105'], array_column((array) $a['senders'], 'sender'));
    $guide = "$tmp/advisor/network.json";
    advisorNetworkSeen($guide, $now);
    same('net advisor: the router guide opened — noted (root only) for the Team Lead', [$now, 0600], [watchnetGuideSeen($guide), fileperms($guide) & 0777]);

    // ---- Ms. Protocolli's sources: every sender's file (ids, never paths from a request), its rotated part; her tour skips .1
    $lf = watchnetLogFiles(['cfg' => $paths['rsyslog_cfg'], 'disks_ini' => $paths['disks_ini'], 'shares_ini' => $paths['shares_ini']]);
    same('net logs: router:<sender> and router.1:<sender> (an address may end in .1 itself) — the loop\'s file too (it is a log); the tour leaves .1 out',
        [true, true, true, false, true],
        [isset($lf['router:192.0.2.1']), isset($lf['router.1:192.0.2.1']), isset($lf['router:192.0.2.20']), logsTourWanted('router.1:192.0.2.1'), logsTourWanted('router:192.0.2.1')]);
    foreach (['en', 'de', 'it', 'fr', 'es'] as $lang) {
        $l = json_decode((string) file_get_contents(OFFICE_WEB . "/desks/logs/lang/$lang.json"), true) ?: [];
        check("net logs: the source names ($lang)", isset($l['source.router'], $l['source.router_old']));
    }

    // ---- Mr. Backupsy's setup: the share Unraid's syslog server writes into is proposed «not backed up» (setup.sh's syslog_share())
    $sh = (string) file_get_contents(OFFICE_DIR . '/backup/setup.sh');
    $fn = preg_match('/^syslog_share\(\) \{.*?^\}$/ms', $sh, $m) ? $m[0] : '';
    $run = fn (string $cfg) => trim((string) shell_exec('bash -c ' . escapeshellarg($fn . "\nUB_RSYSLOG_CFG=" . escapeshellarg($cfg) . " syslog_share; echo \" \$?\"")));
    $cfgFile([]);
    file_put_contents("$tmp/off.cfg", "local_server=\"\"\nserver_folder=\"/mnt/user/syslog\"\n");
    same('net backup: setup.sh knows the syslog server\'s share (on), not when it is off', ['syslog 0', '1'], [$run($paths['rsyslog_cfg']), $run("$tmp/off.cfg")]);
    check('net backup: share_propose proposes it not backed up (why code syslog)', (bool) preg_match('/syslog_share\)" && \[\[ "\$s" == "\$sl" \]\]; then\s+why "\$s" syslog ""[^\n]*PROP_MODE=off/', $sh));
    $bl = json_decode((string) file_get_contents(OFFICE_WEB . '/desks/backup/lang/en.json'), true) ?: [];
    check('net backup: the page says why', isset($bl['setup.why.syslog']));

    unset($GLOBALS['watchnetIfaces']);
    @unlink(watchmanLockFile($data, 'book'));
    @unlink(watchmanLockFile($data, 'round'));
    exec('rm -rf ' . escapeshellarg($tmp));
}

// ===================================================================== updates

/**
 * The data folder's version marker and the one place for migrations (agent/lib/migrate.php): an old data folder (an
 * agent.json of 1.30) gets its marker at the first start, a step newer than 1.30 runs once (and renames aside, never
 * deletes), a step older than it doesn't, a failing step is tried again at the next start, a second start does nothing;
 * a fresh folder, a folder of an unknown version, a downgrade, an older office in between; the real steps; the hook in
 * setUp() before anything reads state.
 */
function testMigrate(): void
{
    $tmp = sys_get_temp_dir() . '/office-tests-migrate-' . getmypid();
    exec('rm -rf ' . escapeshellarg($tmp));
    $dir = "$tmp/data";
    @mkdir($dir, 0755, true);
    file_put_contents("$dir/agent.json", '{"running":false,"version":"1.30.0","pid":1}');
    file_put_contents("$dir/caretaker.json", '{"time":1}');
    file_put_contents("$dir/whereabouts.json", '{"old":true}');
    $ran = ['a' => 0, 'b' => 0, 'c' => 0];
    $fail = 1;
    $steps = [
        ['id' => 'b', 'version' => '1.20.0', 'run' => function () use (&$ran): string { $ran['b']++; return 'b'; }],
        ['id' => 'a', 'version' => '1.31.0', 'run' => function (string $d, string $to) use (&$ran): string {
            $ran['a']++;
            return 'aside: ' . basename((string) officeMigrateAside("$d/whereabouts.json", $to));
        }],
        ['id' => 'c', 'version' => '1.40.0', 'run' => function () use (&$ran, &$fail): string {
            $ran['c']++;
            if ($fail-- > 0) {
                throw new RuntimeException('not now');
            }
            return 'c';
        }],
    ];
    $lines = [];
    $log = function (string $l) use (&$lines): void { $lines[] = $l; };
    $start = function (string $to, ?array $s = null) use ($dir, &$steps, $log, &$lines): ?array {
        $lines = [];
        return officeMigrateStart($dir, $to, $s ?? $steps, $log);
    };
    $agentIs = fn (string $v) => file_put_contents("$dir/agent.json", jsonEncode(['running' => true, 'version' => $v]));     // what writeInfo() does next

    same('migrate: an old folder comes from its agent.json', ['1.30.0', null], officeMigrateFrom($dir));
    $r = $start('1.41.0');
    $mark = officeMarkRead($dir);
    same('migrate: the first start — the newer steps run (the failing one stays pending), the older one is counted done',
        [['a'], ['c'], ['a' => 1, 'b' => 0, 'c' => 1]], [$r['ran'], $r['failed'], $ran]);
    same('migrate: the marker — version, since, where it came from, done, pending',
        ['1.41.0', true, [['version' => '1.30.0']], ['b', 'a'], ['c']],
        [$mark['version'] ?? null, ($mark['since'] ?? 0) >= time() - 5, array_map(fn ($u) => ['version' => $u['version']], $mark['updated_from'] ?? []),
         $mark['done'] ?? null, $mark['pending'] ?? null]);
    same('migrate: the marker is exactly the office\'s shape', ['version', 'since', 'updated_from', 'done', 'pending'], array_keys(readJson("$dir/office.json") ?? []));
    same('migrate: what made way is renamed aside, never deleted; the rest untouched', [false, '{"old":true}', '{"time":1}'],
        [file_exists("$dir/whereabouts.json"), @file_get_contents("$dir/whereabouts.json.before-1.41.0"), file_get_contents("$dir/caretaker.json")]);
    check('migrate: logged — the marker, each step, the failure', count($lines) === 3 && str_contains($lines[0], 'version marker written')
        && str_contains($lines[0], '1.30.0') && str_contains($lines[1], 'step a') && str_contains($lines[2], 'step c') && str_contains($lines[2], 'failed'), json_encode($lines));
    $agentIs('1.41.0');
    $since = $mark['since'];
    touch("$dir/office.json", 1000000000);
    $r = $start('1.41.0');
    same('migrate: the next start tries the failed step again — only that one', [['c'], [], ['a' => 1, 'b' => 0, 'c' => 2]], [$r['ran'], $r['failed'], $ran]);
    same('migrate: … and the marker keeps its since', [$since, ['b', 'a', 'c'], []], [officeMarkRead($dir)['since'], officeMarkRead($dir)['done'], officeMarkRead($dir)['pending']]);
    $before = file_get_contents("$dir/office.json");
    touch("$dir/office.json", 1000000000);
    $r = $start('1.41.0');
    clearstatcache();
    same('migrate: a second start does nothing — no step, no line, the marker not written', [[], [], ['a' => 1, 'b' => 0, 'c' => 2], $before, 1000000000],
        [$r['ran'], $lines, $ran, file_get_contents("$dir/office.json"), filemtime("$dir/office.json")]);
    same('migrate: what made way stays aside (a second aside gets a number)', basename("$dir/x.before-1.41.0-2"),
        (function () use ($dir) { file_put_contents("$dir/x", '1'); file_put_contents("$dir/x.before-1.41.0", '0'); return basename((string) officeMigrateAside("$dir/x", '1.41.0')); })());
    same('migrate: nothing there — nothing renamed', null, officeMigrateAside("$dir/none", '1.41.0'));

    // an update: from the marker's version; since and updated_from move on
    $r = $start('1.42.0');
    $mark = officeMarkRead($dir);
    same('migrate: an update — nothing left to do, the marker moves on', [[], '1.42.0', ['1.30.0', '1.41.0']],
        [$r['ran'], $mark['version'], array_column($mark['updated_from'], 'version')]);
    check('migrate: … said once', count($lines) === 1 && str_contains($lines[0], '1.41.0 → 1.42.0'), json_encode($lines));
    $agentIs('1.42.0');

    // a downgrade that knows the marker: only its own steps count, the newer one's run again when it comes back
    $r = $start('1.40.5', array_slice($steps, 0, 2));
    $mark = officeMarkRead($dir);
    same('migrate: a downgrade — said, nothing run, only the steps it knows kept as done', [true, [], ['b', 'a'], '1.40.5'],
        [$r['downgrade'], $r['ran'], $mark['done'], $mark['version']]);
    check('migrate: … the downgrade in the log', count($lines) === 1 && str_contains($lines[0], 'a downgrade'), json_encode($lines));
    $agentIs('1.40.5');
    $r = $start('1.42.0');
    same('migrate: back again — the step it didn\'t know runs again (idempotent)', [['c'], ['a' => 1, 'b' => 0, 'c' => 3]], [$r['ran'], $ran]);
    $agentIs('1.42.0');

    // an office from before the marker ran in between (it wrote agent.json, not office.json): the steps since it run again
    $agentIs('1.35.0');
    same('migrate: an older agent.json than the marker — an office from before the marker ran in between', ['1.35.0', '1.35.0'], officeMigrateFrom($dir));
    $r = $start('1.42.0');
    same('migrate: … the steps newer than it run again, the older ones not', [['c'], ['a' => 1, 'b' => 0, 'c' => 4]], [$r['ran'], $ran]);
    same('migrate: … the way it went in updated_from', ['1.30.0', '1.41.0', '1.42.0', '1.40.5', '1.42.0', '1.35.0'],
        array_column(officeMarkRead($dir)['updated_from'], 'version'));
    check('migrate: … said', str_contains($lines[0] ?? '', '1.35.0 (from before the marker)'), json_encode($lines));

    // a fresh folder: nothing to change, every step done; a folder with state files but no version: every step runs
    $fresh = "$tmp/fresh";
    @mkdir($fresh, 0755, true);
    $count = $ran;
    same('migrate: a fresh folder', ['', null], officeMigrateFrom($fresh));
    $r = officeMigrateStart($fresh, '1.42.0', $steps, $log);
    same('migrate: … no step runs, all done, the marker written', [[], $count, ['b', 'a', 'c'], '1.42.0', []],
        [$r['ran'], $ran, officeMarkRead($fresh)['done'], officeMarkRead($fresh)['version'], officeMarkRead($fresh)['updated_from']]);
    $unknown = "$tmp/unknown";
    @mkdir($unknown, 0755, true);
    file_put_contents("$unknown/backup.json", '{}');
    same('migrate: state files without a version — unknown, older than all', ['0', null], officeMigrateFrom($unknown));
    $fail = 0;
    $r = officeMigrateStart($unknown, '1.42.0', $steps, $log);
    same('migrate: … every step runs', ['b', 'a', 'c'], $r['ran']);
    @mkdir("$tmp/broken", 0755, true);
    file_put_contents("$tmp/broken/office.json", '{"version":"x y","done":["a"]}');
    same('migrate: a marker not in the office\'s shape counts as none', [], officeMarkRead("$tmp/broken"));

    // the real steps: unique ids, versions, callables — the first changes nothing in the folder
    $real = officeMigrateSteps();
    $ids = array_column($real, 'id');
    check('migrate: the real steps — unique ids, a version each, callable', $ids && count($ids) === count(array_unique($ids))
        && !array_filter($real, fn ($s) => !preg_match(OFFICE_MARK_VERSION, (string) ($s['version'] ?? '')) || !is_callable($s['run'] ?? null)
            || !preg_match('/^[a-z0-9][a-z0-9-]*\z/', (string) $s['id'])));
    $listing = fn () => scandir($dir);
    $was = $listing();
    $r = officeMigrate('1.41.0', '1.42.0', $dir, null, null, $log);
    same('migrate: the real steps run on an older folder — with nothing of the past in it they change nothing', [true, true, $was],
        [in_array('marker', $r['ran'], true) || in_array('marker', officeMarkRead($dir)['done'], true),
         !array_diff(['where-files', 'staff-merged'], array_merge($r['ran'], officeMarkRead($dir)['done'])), $listing()]);
    $versions = array_column($real, 'version');
    usort($versions, 'version_compare');
    same('migrate: the real steps are listed oldest first (they run in that order)', $versions, array_column($real, 'version'));

    // the hook: in setUp(), after the private folders, before agent.json is written and before any desk's start
    $src = (string) file_get_contents(OFFICE_DIR . '/agent/agent.php');
    $setUp = preg_match('/^function setUp\(\): void\n\{\n(.*?)^\}/ms', $src, $m) ? $m[1] : '';
    $at = fn (string $s) => strpos($setUp, $s);
    check('migrate: setUp() runs officeMigrateStart() before writeInfo() and the desks\' start', $at('officeMigrateStart()') !== false
        && $at('officeMigrateStart()') < $at('writeInfo(true)') && $at('officeMigrateStart()') < $at("(\$desk['start'])()") && $at('privateDirEnsure(OFFICE_PRIVATE') < $at('officeMigrateStart()'));
    check('migrate: the agent requires lib/migrate.php', str_contains($src, "require __DIR__ . '/lib/migrate.php';"));
    exec('rm -rf ' . escapeshellarg($tmp));
}

/**
 * Mr. Backupsy's setup after an engine update (upgrade audit proposal 5, backupSetupReplan()): a plan whose `version`
 * isn't the running engine's is made anew on the next look — once per engine version (the note is written before
 * setup.sh starts; a failed plan isn't tried again at every look), not while a run or anything holds the lock, not for
 * an engine the office can't drive; no plan answered while it runs; the plan it made says so in its messages (once —
 * a later plan doesn't); the page no longer sniffs the plan's shape.
 */
function testBackupReplan(): void
{
    $state = ['found' => true, 'compatible' => true, 'running' => false, 'version' => '2.34'];
    $old = ['version' => '2.33', 'time' => 100, 'messages' => [['level' => 'warn', 'step' => 'shares', 'text' => 'x']]];
    $r = backupSetupReplan($old, $state, null, true, 1000);
    same('backup replan: an older engine\'s plan — planned anew, no plan answered meanwhile, the note first',
        [null, true, ['from' => '2.33', 'to' => '2.34', 'at' => 1000]], [$r['plan'], $r['start'], $r['note']]);
    $note = $r['note'];
    $r = backupSetupReplan($old, $state, $note, true, 1060);
    same('backup replan: … once — the plan failed (still the old one): not again, the old plan shown', [$old, false, $note], [$r['plan'], $r['start'], $r['note']]);
    foreach ([['running' => true], ['compatible' => false], ['found' => false]] as $odd) {
        $r = backupSetupReplan($old, $odd + $state, null, true, 1000);
        same('backup replan: not now — ' . json_encode($odd), [$old, false, null], [$r['plan'], $r['start'], $r['note']]);
    }
    $r = backupSetupReplan($old, $state, null, false, 1000);
    same('backup replan: not while something holds the engine\'s lock (setup, restore, recover)', [$old, false, null], [$r['plan'], $r['start'], $r['note']]);
    $r = backupSetupReplan(['time' => 5], $state, null, true, 1000);
    same('backup replan: a plan without a version counts as older', [true, '?'], [$r['start'], $r['note']['from'] ?? null]);
    $r = backupSetupReplan(null, $state, null, true, 1000);
    same('backup replan: no plan at all — nothing here (the page asks for its first plan itself)', [null, false], [$r['plan'], $r['start']]);

    // the new plan: said in its messages, the note remembers which plan that was
    $new = ['version' => '2.34', 'time' => 1003, 'messages' => [['level' => 'info', 'step' => 'plan', 'text' => 'Plan written']]];
    $r = backupSetupReplan($new, $state, $note, true, 1010);
    $said = $r['plan']['messages'][1] ?? [];
    same('backup replan: the plan made anew says so in its list (code replanned, the versions)',
        [false, 'Plan written', 'replanned', 'info', ['from' => '2.33', 'to' => '2.34'], 1003],
        [$r['start'], $r['plan']['messages'][0]['text'] ?? null, $said['code'] ?? null, $said['level'] ?? null, $said['params'] ?? null, $r['note']['plan'] ?? null]);
    $r2 = backupSetupReplan($new, $state, $r['note'], true, 1200);
    same('backup replan: … on every look at that plan', 'replanned', $r2['plan']['messages'][1]['code'] ?? null);
    $later = ['version' => '2.34', 'time' => 2000, 'messages' => []];
    $r3 = backupSetupReplan($later, $state, $r['note'], true, 2010);
    same('backup replan: a later plan (Look again, after Apply) says nothing of it', [[], false], [$r3['plan']['messages'], $r3['start']]);
    $r4 = backupSetupReplan($new, $state, null, true, 1010);
    same('backup replan: this engine\'s plan without a note — as it is', $new, $r4['plan']);
    $r5 = backupSetupReplan($old, ['version' => '2.35'] + $state, $r['note'], true, 3000);
    same('backup replan: the next engine update — planned anew again', [true, '2.35'], [$r5['start'], $r5['note']['to'] ?? null]);

    $src = (string) file_get_contents(OFFICE_DIR . '/agent/desks/backup.php');
    $get = preg_match('/^function backupSetupGet\(\): array\n\{\n(.*?)^\}/ms', $src, $m) ? $m[1] : '';
    check('backup replan: setup_get decides, notes before it starts, and starts setup.sh --plan',
        str_contains($get, 'backupSetupReplan(') && strpos($get, 'writeAtomic($noteFile') < strpos($get, "'--plan'") && str_contains($get, "\$replan['start'] = false"));
    $js = (string) file_get_contents(OFFICE_WEB . '/desks/backup/desk.js');
    check('backup replan: the page no longer sniffs the plan\'s shape', !str_contains($js, 'restale') && !str_contains($js, 'c.binds === undefined'));
    $en = json_decode((string) file_get_contents(OFFICE_WEB . '/desks/backup/lang/en.json'), true) ?: [];
    check('backup replan: the office has its words', str_contains((string) ($en['setup.msg.replanned'] ?? ''), '{from}') && str_contains((string) ($en['setup.msg.replanned'] ?? ''), '{to}'));
}

/**
 * Unraid 8 and the .plg's max (upgrade audit proposal 7): the version the office was tested on is one constant
 * (OFFICE_UNRAID_TESTED, src/place.php), the .plg's max is <major>.99.99 of it (plugin/build.sh refuses another); the
 * team lead recommends looking for an office release before an Unraid update once this Unraid is newer than the tested
 * major.minor or within the last minor before max — in place on the tested one and older.
 */
function testUnraidTested(): void
{
    $ok = fn (?string $v, string $t = '7.3') => ($f = caretakerUnraidTested($v, $t)) === null ? null : $f['ok'];
    same('unraid tested: the tested one and older — in place', [true, true, true, true], [$ok('7.3.2'), $ok('7.3.0'), $ok('7.2.4'), $ok('7.3.0-rc.1')]);
    same('unraid tested: newer than tested — look for an office release first', [false, false, false], [$ok('7.4.0'), $ok('7.4.0-beta.2'), $ok('7.10.1')]);
    same('unraid tested: within the last minor before max (7.99.x) — also when tested that far', [false, false], [$ok('7.99.0', '7.99'), $ok('7.99.5')]);
    same('unraid tested: version unknown — nothing said', [null, null], [$ok(null), $ok('weird')]);
    $f = caretakerUnraidTested('7.4.1', '7.3');
    same('unraid tested: the finding — recommended (never a must), its params, Unraid\'s Plugins page',
        ['unraid_tested', 'recommended', ['version' => '7.4.1', 'tested' => '7.3', 'next' => '8'], 'plugins'], [$f['id'], $f['level'], $f['params'], $f['link']]);
    $en = json_decode((string) file_get_contents(OFFICE_WEB . '/desks/caretaker/lang/en.json'), true) ?: [];
    check('unraid tested: the team lead has its words (tested, version, next)', isset($en['check.unraid_tested'])
        && str_contains((string) ($en['check.unraid_tested_how'] ?? ''), '{tested}') && str_contains((string) ($en['check.unraid_tested_how'] ?? ''), '{next}'));
    check('unraid tested: one constant, major.minor', (bool) preg_match('/^\d+\.\d+\z/', OFFICE_UNRAID_TESTED));
    $plg = (string) file_get_contents(OFFICE_DIR . '/plugin/unraid-secretary-office.plg');
    same('unraid tested: the .plg\'s max agrees with it', officeUnraidMax(), preg_match('/\smax="([^"]+)"/', $plg, $m) ? $m[1] : null);
    $src = (string) file_get_contents(OFFICE_DIR . '/agent/desks/caretaker.php');
    check('unraid tested: the team lead\'s checks ask for it', str_contains($src, 'caretakerUnraidTested($version)'));

    // build.sh refuses a .plg whose max doesn't agree (a stand-in tree with only what its first checks read)
    $tmp = hardeningTmp('unraid-tested');
    $build = function (string $max) use ($tmp): string {
        exec('rm -rf ' . escapeshellarg("$tmp/tree"));
        @mkdir("$tmp/tree/plugin", 0700, true);
        @mkdir("$tmp/tree/src", 0700, true);
        @mkdir("$tmp/tree/agent", 0700, true);
        copy(OFFICE_DIR . '/plugin/build.sh', "$tmp/tree/plugin/build.sh");
        foreach (['src/place.php', 'src/bootstrap.php', 'agent/agent.php'] as $f) {
            copy(OFFICE_DIR . "/$f", "$tmp/tree/$f");
        }
        file_put_contents("$tmp/tree/plugin/unraid-secretary-office.plg", preg_replace('/(\s)max="[^"]+"/', '$1max="' . $max . '"',
            (string) file_get_contents(OFFICE_DIR . '/plugin/unraid-secretary-office.plg'), 1));
        return (string) shell_exec('cd ' . escapeshellarg("$tmp/tree") . ' && bash plugin/build.sh ' . escapeshellarg(AGENT_VERSION) . ' 2026.10.08 2>&1');
    };
    $bad = $build('8.99.99');
    check('unraid tested: build.sh refuses a max beyond the tested major', str_contains($bad, "the .plg's max is '8.99.99'"), $bad);
    $good = $build(officeUnraidMax());
    check('unraid tested: … and passes the one that agrees', !str_contains($good, "the .plg's max") && !str_contains($good, 'OFFICE_UNRAID_TESTED'), $good);
    hardeningRm($tmp);
}

/**
 * The .plg refuses an update while one of the office's long jobs runs from the plugin folder outside the agent: a backup
 * run or the setup (atd, cron), Mr. Restori's restore or drill, Jack Emby's EmbyCache or gather — one pgrep -f
 * pattern; the agent, its night shift and the short jobs don't hold it up. pgrep matches POSIX EREs against the whole
 * command line, as grep -E does here.
 */
function testPlgGuard(): void
{
    $plg = (string) file_get_contents(OFFICE_DIR . '/plugin/unraid-secretary-office.plg');
    $line = preg_match('/^jobs="([^"\n]+)"$/m', $plg, $m) ? $m[1] : '';
    check('plg guard: the pattern is one plain string, pgrep -f uses it', $line !== '' && str_contains($plg, 'pgrep -f "$jobs"'));
    $dir = '/usr/local/emhttp/plugins/unraid-secretary-office';
    $pattern = str_replace(['$dir', '\\$'], [$dir, '$'], $line);
    $hit = function (string $cmd) use ($pattern): bool {
        exec('printf "%s\n" ' . escapeshellarg($cmd) . ' | grep -qE ' . escapeshellarg($pattern), $o, $code);
        return $code === 0;
    };
    $busy = [
        "/bin/bash $dir/backup/backup.sh --check",                              // atd (backupLaunch)
        "bash $dir/backup/backup.sh",                                           // cron (job.sh's exec)
        "/bin/bash $dir/backup/backup.sh --recover",                            // agent.sh backup_recover
        "/bin/bash $dir/backup/setup.sh --plan",
        "/usr/bin/php $dir/agent/agent.php job restore 20261008-125107-32f9",   // hostLaunch (PHP_BINARY)
        "/usr/bin/php $dir/agent/agent.php job restore-drill 20261008-011005-57db",
        "/usr/bin/php $dir/agent/agent.php job gather run --office",
        "php $dir/agent/agent.php job embycache",                               // cron (job.sh's exec)
        "php $dir/agent/agent.php job gather",
    ];
    $free = [
        "php $dir/agent/agent.php run",
        "php $dir/agent/agent.php nightshift",
        "php $dir/agent/agent.php job snapshot-plans",
        "/usr/bin/php $dir/agent/agent.php job restore-partner-look",
        "/usr/bin/php $dir/agent/agent.php job partner-ping",
        "nice -n 10 /usr/bin/php $dir/agent/agent.php job logs-tour",
        "bash $dir/scripts/agent.sh supervise",
        "grep $dir/backup/backup.sh",
        "/usr/bin/php /tmp/x/agent/agent.php job restore 1",
        "bash /tmp/uso-upgrade/backup/backup.sh",
    ];
    same('plg guard: these hold the update up', array_fill(0, count($busy), true), array_map($hit, $busy));
    same('plg guard: these don\'t', array_fill(0, count($free), false), array_map($hit, $free));
    $guard = strpos($plg, 'pgrep -f "$jobs"');
    check('plg guard: before the agent is stopped and the folder replaced', $guard !== false && $guard < strpos($plg, 'scripts/agent.sh" stop') && $guard < strpos($plg, 'rm -rf "$dir"'));
    // the install: unpacked beside and checked before the agent is stopped, then the swap — two renames
    $install = plgScript('install', '/x');
    $at = fn (string $what) => strpos($install, $what);
    check('plg install: the guard, then unpacked beside and checked, then the old agent stopped, the swap, the new agent started',
        $at('pgrep -f "$jobs"') < $at('tar -xJf "$package" -C "$new"') && $at('tar -xJf "$package" -C "$new"') < $at('[ ! -f "$new/$name/scripts/partner-door.sh" ]')
        && $at('[ ! -f "$new/$name/scripts/partner-door.sh" ]') < $at('bash "$dir/scripts/agent.sh" stop') && $at('bash "$dir/scripts/agent.sh" stop') < $at('mv "$dir" "$old/$name"')
        && $at('mv "$dir" "$old/$name"') < $at('mv "$new/$name" "$dir"') && $at('mv "$new/$name" "$dir"') < $at('officeMenuPageApply')
        && $at('officeMenuPageApply') < $at('bash "$dir/scripts/agent.sh" start;') && !str_contains($install, 'rm -rf "$dir"'));
    check('plg install: nothing of the array or var.ini (a boot install runs before emhttp)', !preg_match('/^[^#\n]*(var\.ini|fsState|mdState)/m', $install));
    // the remove: the same guard, first; what the office holds let go before the code goes
    $remove = plgScript('remove', '/x');
    same('plg remove: the same pattern as the install', [$line], preg_match('/^jobs="([^"\n]+)"$/m', $remove, $m) ? [$m[1]] : []);
    $at = fn (string $what) => strpos($remove, $what);
    check('plg remove: the guard first, then agent.sh release, the schedules aside, then the folder goes', $at('pgrep -f "$jobs"') !== false
        && $at('pgrep -f "$jobs"') < $at('bash "$dir/scripts/agent.sh" release') && $at('bash "$dir/scripts/agent.sh" release') < $at('.cron.removed-$stamp')
        && $at('.cron.removed-$stamp') < $at('rm -rf "$dir"'));
}

/**
 * Exact shapes, tolerant writes (CLAUDE.md «Updates», briefs/upgrade-audit.md finding 4): pairs.json, tickets.json and
 * ticket-pairs.json keep every entry a version doesn't recognise — a newer office's, met after a downgrade — where it
 * stood, as it was, through every write that touches another entry; a file of another `v` is not written over.
 */
function testPartnerTolerant(): void
{
    if (posix_geteuid() !== 0) {
        check('partner tolerant writes: root only — not run here', true);
        return;
    }
    $tmp = hardeningTmp('partner-tolerant');
    exec('rm -rf ' . escapeshellarg($tmp) . '/*');
    $file = "$tmp/partner/pairs.json";
    $a = partnerTestPair('a1b2c3d4');
    partnerPairsWrite([$a], $file);
    $raw = fn (): array => json_decode((string) file_get_contents($file), true);
    // from «the future»: a pair with a field this version doesn't know, an entry of a kind it doesn't know, a key beside
    $f1 = partnerTestPair('f1f1f1f1', ['name' => 'later', 'compress' => 'zstd']);
    $f2 = ['id' => 'f2f2f2f2', 'kind' => 'mirror', 'name' => 'mirrorbox', 'address' => '192.168.77.8', 'schedule' => ['every' => 'hour'], 'extra' => [1, 2.5, null, true]];
    $future = ['v' => 1, 'pairs' => [$f1, $a, $f2], 'mirrors_since' => 1791336000];
    file_put_contents($file, json_encode($future, JSON_UNESCAPED_SLASHES) . "\n");
    chmod($file, 0600);
    same('tolerant: the reader takes only the pair in this version\'s shape', ['a1b2c3d4'], array_column(partnerPairs($file), 'id'));
    // a write that touches another entry: the future ones where they stood, as they were
    $a2 = ['name' => 'renamed'] + $a;
    partnerPairsWrite([$a2], $file);
    same('tolerant: a write that changes another pair keeps the future entries where they stood, field for field, and the key beside',
        ['v' => 1, 'pairs' => [$f1, $a2, $f2], 'mirrors_since' => 1791336000], $raw());
    $b = partnerTestPair('b2c3d4e5', ['their_key' => null, 'receive' => null]);
    partnerPairsWrite([$a2, $b], $file);
    same('tolerant: a new pair at the end', ['f1f1f1f1', 'a1b2c3d4', 'f2f2f2f2', 'b2c3d4e5'], array_column($raw()['pairs'], 'id'));
    partnerPairsWrite([$b], $file);
    same('tolerant: a pair ended goes, the future ones stay', [$f1, $f2, $b], $raw()['pairs']);
    // an old-shape pair (send before 2.29) is this version's: written in the whole shape, in its place
    $old = $raw();
    $old['pairs'][2]['send'] = ['units' => ['share:media'], 'rate_mbit' => 0];
    file_put_contents($file, json_encode($old, JSON_UNESCAPED_SLASHES));
    partnerPairsWrite(partnerPairs($file), $file);
    same('tolerant: an old-shape pair upgraded in its place, the others untouched', [$f1, $f2, array_replace($b, ['send' => ['units' => ['share:media'], 'rate_mbit' => 0, 'wanted' => ['share:media'], 'offered' => null]])],
        $raw()['pairs']);
    // a file of another v: not this version's to write
    $v2 = json_encode(['v' => 2, 'pairs' => [$a]]);
    file_put_contents($file, $v2);
    try {
        partnerPairsWrite([$b], $file);
        check('tolerant: a pairs.json of another v is not written over', false);
    } catch (Problem $e) {
        same('tolerant: a pairs.json of another v is not written over', ['partner_shape', $v2], [$e->key, file_get_contents($file)]);
    }

    // tickets.json and ticket-pairs.json, the same way (written by the office's own functions, as that office)
    $B = partnerTestOffice("$tmp/B");
    $now = time();
    $ticket = fn (string $tid, array $over = []) => $over + ['id' => $tid, 'of' => 'a1b2c3d4', 'name' => 'newbox', 'address' => '192.168.77.9', 'from' => '192.168.77.9',
        'key' => partnerFingerprint(partnerTestKey()), 'created' => $now - 60, 'expires' => $now + 3600, 'units' => ['share:appdata']];
    partnerTestAs($B, 'partnerTicketsWrite(' . var_export([$ticket('c3c3c3c3')], true) . '); return true;');
    $tf = "$B[data]/partner/tickets.json";
    $ft = $ticket('e5e5e5e5', ['scope' => 'all']);
    file_put_contents($tf, json_encode(['v' => 1, 'tickets' => [$ft, $ticket('c3c3c3c3')]]));
    $d4 = $ticket('d4d4d4d4');
    partnerTestAs($B, 'partnerTicketsWrite(' . var_export([$d4], true) . '); return true;');
    same('tolerant: tickets.json — a future ticket kept, the one given up gone, the new one at the end', ['v' => 1, 'tickets' => [$ft, $d4]],
        json_decode((string) file_get_contents($tf), true));
    same('tolerant: … and never used', ['d4d4d4d4'], array_column(partnerTestAs($B, 'return partnerTickets();'), 'id'));
    $pf = "$B[data]/partner/ticket-pairs.json";
    $tp = ['id' => 'c3c3c3c3', 'kind' => 'ticket', 'name' => 'oldbox', 'of' => 'nostromo', 'address' => '192.168.77.2', 'port' => 22,
           'host_keys' => [partnerFingerprint(partnerTestKey())], 'my_key' => partnerFingerprint(partnerTestKey()), 'units' => ['share:appdata'],
           'expires' => $now + 3600, 'paired' => $now - 60, 'last_heard' => null];
    $ftp = ['kind' => 'restore-all', 'id' => 'e6e6e6e6'] + $tp;
    file_put_contents($pf, json_encode(['v' => 1, 'pairs' => [$ftp]]));
    chmod($pf, 0600);
    partnerTestAs($B, 'partnerTicketPairsWrite(' . var_export([$tp], true) . '); return true;');
    same('tolerant: ticket-pairs.json — a future ticket pair kept, the new one at the end', [$ftp, $tp], json_decode((string) file_get_contents($pf), true)['pairs'] ?? null);
    hardeningRm($tmp);
}

/**
 * One of the .plg's inline scripts ('install' or 'remove'), pointed at a folder of the tests: the plugin folder under
 * $root/plugins, the flash $root/flash, the RAM folder $root/run — nothing of the live plugin is touched.
 */
function plgScript(string $method, string $root): string
{
    $plg = (string) file_get_contents(OFFICE_DIR . '/plugin/unraid-secretary-office.plg');
    $re = $method === 'remove' ? '/<FILE Run="\/bin\/bash" Method="remove">\s*<INLINE>\s*<!\[CDATA\[\n(.*?)\]\]>/s'
                               : '/<FILE Run="\/bin\/bash">\s*<INLINE>\s*<!\[CDATA\[\n(.*?)\]\]>/s';
    $s = preg_match($re, $plg, $m) ? $m[1] : '';
    return strtr($s, ['dir=/usr/local/emhttp/plugins/$name' => "dir=$root/plugins/\$name", 'flash=/boot/config/plugins/$name' => "flash=$root/flash",
                      'run=/var/run/$name' => "run=$root/run", 'keys=/boot/config/ssh/root/authorized_keys' => "keys=$root/authorized_keys",
                      '/usr/local/sbin/update_cron' => "$root/update_cron", '@VERSION@' => '2026.10.08', '@OFFICE_VERSION@' => '1.42.0']);
}

/** A stand-in of the plugin folder's agent.sh: each call a line "<marker> <command>" in $USO_PLG_LOG; START and STATUS its exits */
function plgTestAgentSh(): string
{
    return "#!/bin/bash\nhere=\$(cd \"\$(dirname \"\$0\")/..\" && pwd)\necho \"\$(cat \"\$here/marker\") \$*\" >>\"\$USO_PLG_LOG\"\n"
        . "case \"\$1\" in start) exit \${START:-0} ;; status) exit \${STATUS:-3} ;; esac\nexit 0\n";
}

/** The .plg's remove (pointed at the tests' folders): the busy guard, what the office holds let go, the schedules aside */
function testPlgRemove(): void
{
    $tmp = hardeningTmp('plgremove');
    $name = 'unraid-secretary-office';
    $dir = "$tmp/plugins/$name";
    $flash = "$tmp/flash";
    $log = "$tmp/calls.log";
    $script = plgScript('remove', $tmp);
    file_put_contents("$tmp/remove.sh", $script);
    check('plg remove: the script read, pointed at the tests\' folders', str_contains($script, "dir=$tmp/plugins/\$name")
        && !preg_match('#/usr/local/emhttp/plugins/\$name|/boot/config/(plugins|ssh)|/usr/local/sbin#', $script), $script);
    file_put_contents("$tmp/update_cron", "echo update_cron >>\"\$USO_PLG_LOG\"\n");
    $cron = "# Unraid Secretary Office - written by the office, change it there\n0 2 * * * bash /usr/local/emhttp/plugins/$name/scripts/job.sh backup > /dev/null 2>&1\n";
    $benj = "ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIBenjBenjBenjBenjBenjBenjBenjBenjBenjBenj benj@MacBook\n";
    $installed = function () use ($tmp, $dir, $flash, $name, $cron, $benj): void {
        hardeningRm($dir);
        hardeningRm($flash);
        mkdir("$dir/scripts", 0755, true);
        mkdir("$dir/backup", 0755, true);
        mkdir("$flash/partners", 0700, true);
        file_put_contents("$dir/marker", 'old');
        file_put_contents("$dir/scripts/agent.sh", plgTestAgentSh());
        file_put_contents("$dir/backup/backup.sh", "sleep 20\ntrue\n");
        file_put_contents("$flash/$name.cfg", "DATA_DIR=\"/mnt/user/appdata/UnraidSecretaryOffice/data\"\n");
        file_put_contents("$flash/$name.cron", $cron);
        file_put_contents("$flash/$name.cron.removed-20260101-010101", 'an earlier remove\'s');
        file_put_contents("$flash/agent-watch.cron", "*/5 * * * * bash /usr/local/emhttp/plugins/$name/scripts/job.sh watch > /dev/null 2>&1\n");
        file_put_contents("$flash/$name-2026.10.08.txz", 'the package');
        file_put_contents("$flash/partners/a1b2c3d4.key", 'a key');
        file_put_contents("$tmp/authorized_keys", $benj . "ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIPartPartPartPartPartPartPartPartPartPart uso-partner:a1b2c3d4\n");
    };
    $run = function () use ($tmp, $log): array {
        @unlink($log);
        exec('cd / && env USO_PLG_LOG=' . escapeshellarg($log) . ' bash ' . escapeshellarg("$tmp/remove.sh") . ' 2>&1', $out, $code);
        return [$code, implode("\n", $out), is_file($log) ? file($log, FILE_IGNORE_NEW_LINES) : []];
    };
    $asides = fn (): array => array_map('basename', glob("$flash/$name.cron.removed-*") ?: []);

    // busy: a backup run from the plugin folder — nothing removed, nothing released
    $installed();
    $busy = proc_open(['bash', "$dir/backup/backup.sh"], [['file', '/dev/null', 'r'], ['file', '/dev/null', 'w'], ['file', '/dev/null', 'w']], $pipes, '/');
    usleep(200000);
    [$code, $out, $calls] = $run();
    same('plg remove while a backup runs: refused, nothing touched', [1, [], true, $cron, true],
        [$code, $calls, is_dir($dir), @file_get_contents("$flash/$name.cron"), is_file("$flash/partners/a1b2c3d4.key")]);
    check('plg remove while a backup runs: it says why', str_contains($out, 'The office is busy right now') && str_contains($out, 'Nothing was removed'), $out);
    if (is_resource($busy)) {
        proc_terminate($busy, SIGKILL);
        proc_close($busy);
    }

    // the remove: released first (agent.sh release, while the scripts are there), the schedules aside, the rest as before
    [$code, $out, $calls] = $run();
    $aside = $asides();
    same('plg remove: what the office holds let go first, then update_cron, the code gone', [0, ['old release', 'update_cron'], false], [$code, $calls, file_exists($dir)]);
    check('plg remove: the schedules aside, byte for byte, the earlier aside made way', count($aside) === 1 && preg_match('/^' . preg_quote($name) . '\.cron\.removed-\d{8}-\d{6}$/D', $aside[0])
        && $aside[0] !== "$name.cron.removed-20260101-010101" && file_get_contents("$flash/$aside[0]") === $cron && !file_exists("$flash/$name.cron"), json_encode($aside));
    same('plg remove: the watch line, the partners\' keys and their lines, the package and the mirror gone; the .cfg kept',
        [false, false, $benj, false, true], [file_exists("$flash/agent-watch.cron"), file_exists("$flash/partners"), file_get_contents("$tmp/authorized_keys"),
        file_exists("$flash/$name-2026.10.08.txz"), is_file("$flash/$name.cfg")]);
    check('plg remove: it says that the partnerships ended and where the schedules went', str_contains($out, 'partnerships with other offices have ended')
        && str_contains($out, "$flash/$aside[0]") && str_contains($out, 'puts them back'), $out);

    // nothing of that: no word about it
    $installed();
    unlink("$flash/$name.cron");
    hardeningRm("$flash/partners");
    file_put_contents("$tmp/authorized_keys", $benj);
    [$code, $out, $calls] = $run();
    same('plg remove without schedules or partners: done, the earlier aside kept, nothing said of either', [0, ["$name.cron.removed-20260101-010101"], false, false],
        [$code, $asides(), str_contains($out, 'partnerships'), str_contains($out, 'put aside')]);
    // no plugin folder (a broken install): removed all the same
    hardeningRm($dir);
    [$code, , $calls] = $run();
    same('plg remove without the plugin folder: done, nothing to release', [0, []], [$code, $calls]);

    // agent.sh release: what the array stop releases, without the night shift — and the array stop uses it
    $sh = (string) file_get_contents(OFFICE_DIR . '/plugin/scripts/agent.sh');
    $body = preg_match('/^release\(\) \{\n(.*?)^\}/ms', $sh, $m) ? preg_replace('/\s*#.*$/m', '', $m[1]) : '';
    same('agent.sh release: the agent stopped, then drill, partner door, backup mounts, Mr. Restori\'s pulls',
        ['stop', 'drill_release', 'partner_release', 'backup_release', 'restored_release'], preg_split('/\s+/', trim($body)));
    check('agent.sh: the array stop releases the same way, then the night shift; "release" is a command', preg_match('/\n\s+release\s+# [^\n]*\n\s+night_start/', $sh)
        && str_contains($sh, '    release)   release ;;'));
    hardeningRm($tmp);
}

/** officeCronBack(): the schedules a remove put aside, back at the agent's start — only when there is no cron file */
function testCronBack(): void
{
    $tmp = hardeningTmp('cronback');
    $file = "$tmp/unraid-secretary-office.cron";
    $lines = [];
    $applied = 0;
    $apply = function () use (&$applied): void { $applied++; };
    $logf = function (string $l) use (&$lines): void { $lines[] = $l; };
    $cron = '0 2 * * * ' . officeJobCommand('backup') . "\n" . '*/5 * * * * ' . officeJobCommand('snapshots') . "\n";
    same('cron back: nothing aside, nothing done', [null, 0, []], [officeCronBack($file, $apply, $logf), $applied, $lines]);
    file_put_contents("$file.removed-20260101-010101", "an older one\n");
    file_put_contents("$file.removed-20261008-120000", $cron);
    file_put_contents("$file.removed-notatime", "not ours\n");
    same('cron back: the newest aside back, byte for byte, the crontab told', ["$file.removed-20261008-120000", $cron, 1],
        [officeCronBack($file, $apply, $logf), @file_get_contents($file), $applied]);
    check('cron back: said in the log with its jobs', count($lines) === 1 && str_contains($lines[0], 'schedules from before the removal are back')
        && str_contains($lines[0], 'backup, snapshots'), json_encode($lines));
    same('cron back: the others left as they are', ["$file.removed-20260101-010101", "$file.removed-notatime"], glob("$file.removed-*"));
    same('cron back: a cron file there — nothing done', [null, 1, "an older one\n"], [officeCronBack($file, $apply, $logf), $applied, file_get_contents("$file.removed-20260101-010101")]);
    unlink($file);
    symlink("$tmp/elsewhere", "$file.removed-20261009-000000");
    same('cron back: an aside that is a link is none', "$file.removed-20260101-010101", officeCronBack($file, $apply, $logf));
    $src = (string) file_get_contents(OFFICE_DIR . '/agent/agent.php');
    $setUp = preg_match('/^function setUp\(\): void\n\{\n(.*?)^\}/ms', $src, $m) ? $m[1] : '';
    $at = fn (string $s) => strpos($setUp, $s);
    check('cron back: in setUp(), after the steps, before the desks\' start', $at('officeCronBack()') !== false && $at('officeMigrateStart()') < $at('officeCronBack()')
        && $at('officeCronBack()') < $at('foreach (desks()'));
    hardeningRm($tmp);
}

function testPlgInstall(): void
{
    $tmp = hardeningTmp('plginstall');
    $name = 'unraid-secretary-office';
    $dir = "$tmp/plugins/$name";
    $flash = "$tmp/flash";
    $log = "$tmp/calls.log";
    $script = plgScript('install', $tmp);
    file_put_contents("$tmp/install.sh", $script);
    check('plg install: the script read, pointed at the tests\' folders', str_contains($script, "dir=$tmp/plugins/\$name") && !str_contains($script, '/usr/local/emhttp/plugins/$name')
        && !str_contains($script, '/boot/config/plugins/$name') && !str_contains($script, '/var/run/$name'));
    // a package: what the build puts in, as far as the install looks at it
    $pack = function (string $marker, array $leave = [], bool $broken = false) use ($tmp, $name, $flash): void {
        hardeningRm("$tmp/stage");
        $p = "$tmp/stage/$name";
        foreach (['agent', 'scripts', 'backup'] as $d) {
            @mkdir("$p/$d", 0755, true);
        }
        file_put_contents("$p/marker", $marker);
        file_put_contents("$p/agent/agent.php", "<?php\n");
        file_put_contents("$p/scripts/agent.sh", plgTestAgentSh());
        file_put_contents("$p/scripts/partner-door.sh", "#!/bin/bash\n");
        foreach ($leave as $f) {
            unlink("$p/$f");
        }
        @mkdir($flash, 0700, true);
        $txz = "$flash/$name-2026.10.08.txz";
        exec('tar -cJf ' . escapeshellarg($txz) . ' -C ' . escapeshellarg("$tmp/stage") . " $name");
        if ($broken) {
            file_put_contents($txz, substr((string) file_get_contents($txz), 0, 200));
        }
    };
    $old = function () use ($dir): void {          // the version that runs now
        hardeningRm($dir);
        mkdir("$dir/scripts", 0755, true);
        mkdir("$dir/backup", 0755, true);
        file_put_contents("$dir/marker", 'old');
        file_put_contents("$dir/gone.txt", 'only the old version has me');
        file_put_contents("$dir/scripts/agent.sh", plgTestAgentSh());
        file_put_contents("$dir/backup/backup.sh", "sleep 20\ntrue\n");     // not exec'd into sleep: bash stays
    };
    $run = function (array $env = []) use ($tmp, $log): array {
        @unlink($log);
        $e = '';
        foreach ($env + ['USO_PLG_LOG' => $log] as $k => $v) {
            $e .= "$k=" . escapeshellarg((string) $v) . ' ';
        }
        exec("cd / && env $e bash " . escapeshellarg("$tmp/install.sh") . ' 2>&1', $out, $code);
        return [$code, implode("\n", $out), is_file($log) ? file($log, FILE_IGNORE_NEW_LINES) : []];
    };
    $left = fn (): array => array_values(array_filter(scandir("$tmp/plugins") ?: [], fn ($n) => $n !== '.' && $n !== '..' && $n !== $name));

    // at boot: no folder yet — unpacked, put into place, the agent (or the night shift) started
    $pack('new');
    @mkdir("$tmp/plugins", 0755, true);
    [$code, $out, $calls] = $run();
    same('plg install at boot: done, the new version in place, its agent started', [0, 'new', ['new start', 'new status']],
        [$code, @file_get_contents("$dir/marker"), $calls]);
    same('plg install at boot: nothing left beside it', [], $left());
    check('plg install at boot: the .cfg written', str_contains((string) @file_get_contents("$flash/$name.cfg"), 'DATA_DIR="'));
    check('plg install at boot: it says it is installed', str_contains($out, 'Unraid Secretary Office 1.42.0 (plugin 2026.10.08) is installed'));

    // an update: the old agent stopped, the new folder in place of the old one (files the new one lacks are gone), the
    // new agent started, older packages off the flash
    $old();
    file_put_contents("$flash/$name-2026.01.01.txz", 'an older package');
    [$code, , $calls] = $run();
    same('plg update: the old agent stopped, the new one started, the new version in place', [0, ['old stop', 'new start', 'new status'], 'new', false],
        [$code, $calls, @file_get_contents("$dir/marker"), is_file("$dir/gone.txt")]);
    same('plg update: nothing left beside it, the older package gone, this one kept', [[], false, true],
        [$left(), is_file("$flash/$name-2026.01.01.txz"), is_file("$flash/$name-2026.10.08.txz")]);

    // a package that can't be unpacked, or one without what the office needs: nothing changed, the agent never stopped
    foreach (['a damaged package' => [[], true], 'a package without agent.php' => [['agent/agent.php'], false],
              'a package without the partners\' door' => [['scripts/partner-door.sh'], false]] as $what => [$leave, $broken]) {
        $old();
        $pack('new', $leave, $broken);
        [$code, $out, $calls] = $run();
        same("plg update, $what: refused, the old version untouched and running", [1, 'old', true, []],
            [$code, @file_get_contents("$dir/marker"), is_file("$dir/gone.txt"), $calls]);
        check("plg update, $what: it says so", str_contains($out, 'could not be unpacked') && str_contains($out, 'Nothing was changed'), $out);
        same("plg update, $what: nothing left beside it", [], $left());
    }

    // what an install that was cut off left: gone — not a folder of an install running right now
    $old();
    $pack('new');
    mkdir("$tmp/plugins/$name.new-999999999/$name", 0755, true);
    mkdir("$tmp/plugins/$name.old-999999998/$name", 0755, true);
    mkdir("$tmp/plugins/$name.new-" . getmypid(), 0755, true);
    $run();
    same('plg update: an earlier install\'s leftovers gone, a running one\'s kept', ["$name.new-" . getmypid()], $left());
    rmdir("$tmp/plugins/$name.new-" . getmypid());

    // after the swap the new version stays: an agent that doesn't start is said, the install still ends well
    $old();
    [$code, $out, $calls] = $run(['START' => 1]);
    same('plg update, the new agent doesn\'t start: the new version stays, done', [0, 'new', ['old stop', 'new start']], [$code, @file_get_contents("$dir/marker"), $calls]);
    check('plg update, the new agent doesn\'t start: it says so', str_contains($out, 'its agent did not start'), $out);
    // the agent runs: its heartbeat in RAM, written after the start, ends the wait at once
    $old();
    @mkdir("$tmp/run", 0700, true);
    file_put_contents("$tmp/run/agent.json", '{"running":true,"version":"1.42.0"}');
    touch("$tmp/run/agent.json", time() + 5);
    $t = microtime(true);
    [$code, $out] = $run(['STATUS' => 0]);
    check('plg update, the agent checked in: no word about it, no wait', $code === 0 && !str_contains($out, 'checked in') && microtime(true) - $t < 5, $out);

    // busy: a backup run from the plugin folder — refused before anything happens
    $old();
    $busy = proc_open(['bash', "$dir/backup/backup.sh"], [['file', '/dev/null', 'r'], ['file', '/dev/null', 'w'], ['file', '/dev/null', 'w']], $pipes, '/');
    usleep(200000);
    [$code, $out, $calls] = $run();
    same('plg update while a backup runs: refused, nothing touched', [1, 'old', []], [$code, @file_get_contents("$dir/marker"), $calls]);
    check('plg update while a backup runs: it says why', str_contains($out, 'The office is busy right now'), $out);
    if (is_resource($busy)) {
        proc_terminate($busy, SIGKILL);
        proc_close($busy);
    }
    hardeningRm($tmp);
}

/**
 * The engine's lock seen through shfs (QA 2026-10-08, finding 1): on a data folder whose share isn't exclusive the flock
 * lies on the pool's file — /proc/locks names that one, never the inode stat() shows through /mnt/user — so «Stop the
 * run» said «not running». flockHeld() looks for the file behind shfs ((dev << 48) | ino, Unraid 7.3.2), and probes
 * (a shared flock without waiting, let go at once) only a FUSE file whose number names no mounted device. A stand-in
 * holds the lock in a process of its own; the folder is reached two ways; shfs's view is a stat() as it would show it.
 */
function testFlockShfs(): void
{
    $tmp = hardeningTmp('flock');
    mkdir("$tmp/data/state", 0700, true);
    symlink("$tmp/data", "$tmp/user");                   // the same folder a second way
    $lock = "$tmp/data/state/lock";
    touch($lock);
    $p = proc_open([PHP_BINARY, '-r', '$h = fopen($argv[1], "r"); flock($h, LOCK_EX); echo "held\n"; sleep(30);', $lock],
        [0 => ['file', '/dev/null', 'r'], 1 => ['pipe', 'w'], 2 => ['file', '/dev/null', 'w']], $pipes);
    $ready = trim((string) fgets($pipes[1])) === 'held';
    $pid = proc_get_status($p)['pid'];
    check('flock: the stand-in holds the lock', $ready);
    check('flock: held — seen on its path', flockHeld($lock));
    check('flock: … and the other way', flockHeld("$tmp/user/state/lock"));
    file_put_contents("$tmp/data/state/lock-holder.json", json_encode(['holder' => 'restore', 'what' => 'zz-app', 'pid' => $pid, 'started' => time()]));
    same('flock: who holds it, the other way', ['restore', 'zz-app'], [backupLockHolder("$tmp/user")['holder'] ?? null, backupLockHolder("$tmp/user")['what'] ?? null]);

    // the file as /mnt/user of a share that isn't exclusive shows it: shfs's device, (dev << 48) | ino of the file behind
    $st = stat($lock);
    $major = (($st['dev'] >> 8) & 0xfff) | (($st['dev'] >> 32) & ~0xfff);
    $minor = ($st['dev'] & 0xff) | (($st['dev'] >> 12) & ~0xff);
    $shfs = ['dev' => 0x34, 'ino' => (($st['dev'] & 0xffff) << 48) | $st['ino']];
    $fuse = "59 44 0:52 / /mnt/user rw,nosuid,nodev,noatime shared:15 - fuse.shfs shfs rw,user_id=0,group_id=0\n";
    $pool = "48 44 $major:$minor / /mnt/cache rw,noatime shared:5 - zfs cache rw,xattr\n";
    check('flock: its device fits shfs\'s 16 bits (the test\'s own premise)', ($st['dev'] & 0xffff) === $st['dev']);
    check('flock: through shfs, the pool\'s file found', flockHeld($lock, $shfs, $fuse . $pool));
    same('flock: … what it looks for', ['ids' => [flockId(0x34, $shfs['ino']), flockId($st['dev'], $st['ino'])], 'probe' => false], flockIds($shfs, $fuse . $pool));
    // USOPartner, 2026-10-08: stat through /mnt/user dev=2e ino=11258999068426506, /proc/locks 00:28:266 (cache pool, inode 266)
    same('flock: USOPartner\'s numbers', ['ids' => ['00:2e:11258999068426506', '00:28:266'], 'probe' => false],
        flockIds(['dev' => 0x2e, 'ino' => 11258999068426506], "59 44 0:46 / /mnt/user rw - fuse.shfs shfs rw\n48 44 0:40 / /mnt/cache rw - zfs cache rw\n"));
    // a FUSE file whose number names no mounted device: probed — busy while held, never blocking, never taking it away
    same('flock: an unknown FUSE number is probed', true, flockIds($shfs, $fuse)['probe']);
    $t = microtime(true);
    check('flock: the probe says held', flockHeld($lock, $shfs, $fuse));
    check('flock: … at once', microtime(true) - $t < 0.5);
    check('flock: … and the stand-in still holds it', flockHeld($lock) && proc_get_status($p)['running']);
    // anything else that isn't FUSE: only its own id, no probe
    same('flock: a ZFS file with a big inode: its own id only', ['ids' => [flockId(0x34, $shfs['ino'])], 'probe' => false],
        flockIds($shfs, "59 44 0:52 / /mnt/big rw - zfs big rw\n"));
    same('flock: a block device: its own id only', ['ids' => [flockId(0x901, 5)], 'probe' => false], flockIds(['dev' => 0x901, 'ino' => 5], $fuse));

    proc_terminate($p);
    proc_close($p);
    for ($i = 0; $i < 100 && flockHeld($lock); $i++) {
        usleep(20000);
    }
    check('flock: let go — not held, any way', !flockHeld($lock) && !flockHeld("$tmp/user/state/lock") && !flockHeld($lock, $shfs, $fuse . $pool)
        && !flockHeld($lock, $shfs, $fuse));
    same('flock: … nobody holds it', null, backupLockHolder("$tmp/user"));
    exec('flock -n ' . escapeshellarg($lock) . ' true 2>&1', $out, $rc);
    same('flock: the probe let go — a run\'s flock -n takes it', 0, $rc);
    hardeningRm($tmp);
}

/**
 * One run a minute (QA 2026-10-08, finding 3): the run id, its log and the snapshots' name carry the minute — a second
 * «Back up now» in the same minute failed («ZFS snapshot … failed») and left two history lines with one id. The office
 * refuses it (backupMinuteTaken(): the last run's id, or this mode's log), and backup.sh itself ends right after taking
 * the lock when its log is there already — an ERROR line, exit 1, nothing of that run touched (engine 2.34).
 */
function testBackupOneMinute(): void
{
    $tmp = hardeningTmp('minute');
    $data = "$tmp/data";
    @mkdir("$data/state", 0700, true);
    @mkdir("$data/logs", 0700, true);
    $now = mktime(1, 2, 40, 10, 8, 2026);
    same('one a minute: nothing ran yet', null, backupMinuteTaken('backup', $data, $now));
    file_put_contents("$data/state/status.json", json_encode(['run' => '20261008-0101', 'result' => 'ok']));
    same('one a minute: the last run a minute before', null, backupMinuteTaken('backup', $data, $now));
    file_put_contents("$data/state/status.json", json_encode(['run' => '20261008-0102', 'result' => 'ok']));
    same('one a minute: the last run this minute — 20 s to wait', 20, backupMinuteTaken('backup', $data, $now));
    same('one a minute: … whatever the mode', [20, 20, 20], [backupMinuteTaken('nokopia', $data, $now), backupMinuteTaken('dryrun', $data, $now), backupMinuteTaken('check', $data, $now)]);
    file_put_contents("$data/state/status.json", json_encode(['run' => '20261008-0101', 'result' => 'ok']));
    touch("$data/logs/check-20261008-0102.log");
    same('one a minute: a check\'s log this minute — another check waits, a backup not', [20, null], [backupMinuteTaken('check', $data, $now), backupMinuteTaken('backup', $data, $now)]);
    touch("$data/logs/run-20261008-0102.log");
    same('one a minute: a run\'s log this minute', [20, 20, null], [backupMinuteTaken('backup', $data, $now), backupMinuteTaken('nokopia', $data, $now), backupMinuteTaken('dryrun', $data, $now)]);
    $start = (string) file_get_contents(OFFICE_DIR . '/agent/desks/backup.php');
    check('one a minute: backupStart() asks before it launches', ($a = strpos($start, "throw new Problem('one_run_a_minute'")) !== false && $a < strpos($start, 'backupLaunch(array_merge([$dir'));
    $en = json_decode((string) file_get_contents(OFFICE_WEB . '/desks/backup/lang/en.json'), true);
    check('one a minute: its words, with the seconds', str_contains($en['errors.one_run_a_minute'] ?? '', '{seconds}'));

    // the engine: its log of this minute is there (the tests' clock: 2026-10-08 01:02, whatever the real one says)
    $eng = "$tmp/eng";
    @mkdir("$eng/state", 0700, true);
    @mkdir("$eng/logs", 0700, true);
    @mkdir("$tmp/bin", 0700, true);
    touch("$eng/state/lock", 1000);
    testsClock("$tmp/bin", "$tmp/clock", mktime(1, 2, 0, 10, 8, 2026));
    foreach (['run', 'dryrun', 'check'] as $kind) {
        touch("$eng/logs/$kind-20261008-0102.log");
    }
    foreach (['backup' => [], 'dry run' => ['--dry-run'], 'check' => ['--check']] as $what => $args) {
        $p = proc_open(array_merge(['bash', OFFICE_DIR . '/backup/backup.sh'], $args), [0 => ['file', '/dev/null', 'r'], 1 => ['pipe', 'w'], 2 => ['pipe', 'w']], $pipes, null,
            ['UB_DATA' => $eng, 'UB_NO_NOTIFY' => '1', 'PATH' => "$tmp/bin:" . getenv('PATH'), 'OFFICE_RUN_DIR' => TESTS_RUN_DIR]);
        $out = (string) stream_get_contents($pipes[1]);
        $err = (string) stream_get_contents($pipes[2]);
        $rc = proc_close($p);
        check("one a minute: the engine's $what ends — exit 1, an ERROR line", $rc === 1 && str_contains($err, 'ERROR: a run of this minute was made already'), "rc $rc: $out $err");
        clearstatcache();
        same("one a minute: … nothing of the run touched ($what)", [false, false, false, false, 1000],
            [is_file("$eng/state/status.json"), is_file("$eng/state/lock-holder.json"), is_link("$eng/logs/latest.log"), is_file("$eng/state/skipped.json"), filemtime("$eng/state/lock")]);
    }
    same('one a minute: every date call one the tests\' clock knows', '', testsClockUnsupported("$tmp/clock"));
    hardeningRm($tmp);
}

/**
 * Settings are changed only by what a request says (QA 2026-10-08, finding 5): `backup.schedule {}` or `{"cron":[1]}`
 * switched the nightly backup off. A schedule needs `cron` — a line, or null/false/"" for «off»; a switch needs true or
 * false; a form the page always sends whole (Jack Emby's settings and gather, Ms. Snapshotini's plan) needs its parts.
 * Everything here is refused before anything is written.
 */
function testStrictSettings(): void
{
    $refused = function (callable $f): string {
        try {
            $f();
            return 'done';
        } catch (Problem $p) {
            return $p->key;
        }
    };
    $act = fn (string $desk, string $action, array $r): string => $refused(fn () => desks()[$desk]['actions'][$action]($r));
    same('strict: backup.schedule without cron', 'bad_request', $act('backup', 'schedule', []));
    same('strict: backup.schedule with cron of the wrong type', ['bad_request', 'bad_request', 'bad_request', 'bad_request'],
        [$act('backup', 'schedule', ['cron' => [1]]), $act('backup', 'schedule', ['cron' => 5]), $act('backup', 'schedule', ['cron' => true]), $act('backup', 'schedule', ['cron' => ['0 3 * * *']])]);
    same('strict: emby.schedule without cron', 'bad_request', $act('emby', 'schedule', ['job' => 'gather']));
    same('strict: emby.schedule with an array', 'bad_request', $act('emby', 'schedule', ['job' => 'gather', 'cron' => ['x']]));
    same('strict: «off» said', [null, null, null, null], [cronField(['cron' => null]), cronField(['cron' => false]), cronField(['cron' => '']), cronField(['cron' => '  '])]);
    same('strict: a line, trimmed', '0 3 * * *', cronField(['cron' => ' 0 3 * * * ']));
    same('strict: snapshot.plan_toggle without enabled — never «paused»', ['bad_request', 'bad_request'],
        [$act('snapshot', 'plan_toggle', ['id' => 'nosuch']), $act('snapshot', 'plan_toggle', ['id' => 'nosuch', 'enabled' => 'no'])]);
    same('strict: a switch', [true, false, 'bad_request', 'bad_request'], [boolField(['x' => true], 'x'), boolField(['x' => false], 'x'),
        $refused(fn () => boolField([], 'x')), $refused(fn () => boolField(['x' => 1], 'x'))]);
    same('strict: caretaker.menu_name without its place — never back to the menu bar', ['missing_field', 'missing_field'],
        [$act('caretaker', 'menu_name', ['name' => 'Office']), $act('caretaker', 'menu_name', ['name' => 'Office', 'place' => ['menu']])]);
    same('strict: caretaker.menu_name with a name of the wrong type', 'menu_name_bad', $act('caretaker', 'menu_name', ['name' => ['x'], 'place' => 'menu']));
    same('strict: the gather\'s settings — both said', ['emby_bad_number', 'bad_request', 'emby_bad_number', 'bad_request'],
        [$refused(fn () => embyGatherCheck(['shares' => ['media'], 'dup_check' => 'size'], ['media'])), $refused(fn () => embyGatherCheck(['shares' => ['media'], 'min_free_gb' => 5], ['media'])),
         $refused(fn () => embyGatherCheck(['shares' => ['media'], 'min_free_gb' => [5], 'dup_check' => 'size'], ['media'])),
         $refused(fn () => embyGatherCheck(['shares' => ['media'], 'min_free_gb' => 5, 'dup_check' => 'other'], ['media']))]);
    same('strict: the gather\'s settings as the page sends them', ['shares' => ['media'], 'min_free_gb' => 300, 'dup_check' => 'cmp'],
        embyGatherCheck(['shares' => ['media'], 'min_free_gb' => 300, 'dup_check' => 'cmp'], ['media']));
    $inst = ['instances' => [['url' => 'http://10.0.0.5:8096', 'api_key' => 'abcdef0123456789', 'servername' => 'Emby']]];
    same('strict: Jack Emby\'s settings without their lists', 'bad_request', $refused(fn () => embySave($inst)));
    same('strict: … one list missing', 'bad_request', $refused(fn () => embySave($inst + ['libraries' => [], 'library_types' => [], 'valid_users' => []])));
    $plans = (string) file_get_contents(OFFICE_DIR . '/agent/lib/snapshotplans.php');
    check('strict: Ms. Snapshotini\'s plan — its switches said, keep and max_days numbers', str_contains($plans, "\$recursive = boolField(\$in, 'recursive');")
        && str_contains($plans, "\$skipAsleep = boolField(\$in, 'skip_asleep');") && str_contains($plans, '!is_int($keep) || !is_int($days)'));
}

/**
 * Requests of the wrong type are refused, never cast (QA 2026-10-08, findings 6 and 14): Unraid's php.ini hides
 * warnings (error_reporting 22517), so «Array to string conversion» never reached the agent's log. The agent reports
 * everything now (error_reporting(E_ALL) in serve(), agentPhpError(): `@` still silences, the same one once an hour);
 * the malformed requests qa1 sent — arrays where strings belong in partner_*, emby.output tool "../x", office.fire
 * {"desk":["x"]}, ?a=state&desk[]=y — answer bad_request (or unknown_target) and raise no warning.
 */
function testRequestTypes(): void
{
    // the agent's handler: what it logs, what `@` silences, once an hour
    $lines = [];
    $log = function (string $l) use (&$lines): void { $lines[] = $l; };
    $level = error_reporting(E_ALL);
    agentPhpError(E_WARNING, 'Array to string conversion', '/x/partner.php', 1554, $log, 1000);
    agentPhpError(E_WARNING, 'Array to string conversion', '/x/partner.php', 1554, $log, 1001);
    agentPhpError(E_WARNING, 'Array to string conversion', '/x/partner.php', 1554, $log, 2000);
    agentPhpError(E_NOTICE, 'something else', '/x/util.php', 7, $log, 2000);
    agentPhpError(E_WARNING, 'Array to string conversion', '/x/partner.php', 1554, $log, 4700);
    @agentPhpErrorSilenced($log);
    error_reporting($level);
    same('php errors: logged once an hour per place, then with how many came meanwhile', [
        'PHP: Array to string conversion (partner.php:1554)', 'PHP: something else (util.php:7)',
        'PHP: Array to string conversion (partner.php:1554) — 2 more within the hour before'], $lines);
    $agent = (string) file_get_contents(OFFICE_DIR . '/agent/agent.php');
    check('php errors: the agent reports everything from its start', ($e = strpos($agent, 'error_reporting(E_ALL);')) !== false
        && $e < strpos($agent, "set_error_handler('agentPhpError');") && $e > strpos($agent, 'function serve(): int'));

    // the agent's actions with what qa1 sent: refused, and no warning raised
    $warned = [];
    set_error_handler(function (int $no, string $t, string $f, int $l) use (&$warned): bool { $warned[] = "$t (" . basename($f) . ":$l)"; return true; });
    $level = error_reporting(E_ALL);
    $ask = fn (array $r): string => (string) (handle(json_encode($r))['error']['key'] ?? 'ok');
    $staff = TESTS_RUN_DIR . '/types-staff.json';          // the desks asked here work here (testAgentHired: when they don't)
    file_put_contents($staff, json_encode(['hired' => ['emby' => 1, 'restore' => 1]]));
    $GLOBALS['agentStaffFile'] = $staff;
    $answers = [];
    foreach (['partner_add', 'partner_ticket_start'] as $a) {
        $answers[] = $ask(['action' => "caretaker.$a", 'step' => ['x']]);
        $answers[] = $ask(['action' => "caretaker.$a", 'step' => 'do', 'address' => ['x']]);
    }
    foreach (['partner_ping', 'partner_end', 'partner_change', 'partner_wish', 'partner_keep_less', 'partner_ticket_end'] as $a) {
        $answers[] = $ask(['action' => "caretaker.$a", 'id' => ['x'], 'step' => 'look']);
    }
    $answers[] = $ask(['action' => 'caretaker.partner_ticket_make', 'pair' => ['x']]);
    same('types: partner_* with arrays where strings belong — bad_request', array_fill(0, 11, 'bad_request'), $answers);
    same('types: emby.output / emby.log of a tool he hasn\'t — refused, never read as EmbyCache', ['unknown_target', 'unknown_target'],
        [$ask(['action' => 'emby.output', 'tool' => '../x']), $ask(['action' => 'emby.log', 'tool' => '../x'])]);
    same('types: restore.drill_set with nothing it knows — refused, not an ok that changed nothing', 'bad_request', $ask(['action' => 'restore.drill_set', 'x' => 1]));
    unset($GLOBALS['agentStaffFile']);
    @unlink($staff);
    same('types: a text of the wrong type', ['bad_request', 'x', 'd'], [(function () { try { return optText(['a' => [1]], 'a'); } catch (Problem $p) { return $p->key; } })(),
        optText(['a' => 'x'], 'a'), optText([], 'a', 'd')]);
    error_reporting($level);
    restore_error_handler();
    same('types: … and not one warning', [], $warned);

    // the web side: the query and the request
    $web = shell_exec(escapeshellarg(PHP_BINARY) . ' -r ' . escapeshellarg('require ' . var_export(OFFICE_DIR . '/src/bootstrap.php', true) . '; require '
        . var_export(OFFICE_DIR . '/src/api.php', true) . '; error_reporting(E_ALL); $w = []; set_error_handler(function ($n, $t) use (&$w) { $w[] = $t; return true; });'
        . ' $k = function (callable $f) { try { $f(); return "ok"; } catch (OfficeProblem $p) { return $p->key; } };'
        . ' echo json_encode([$k(fn () => apiText(["desk" => ["y"]], "desk")), $k(fn () => apiText(["a" => ["state"]], "a")), apiText([], "lang", "en"),'
        . ' $k(fn () => officeStaffAction("office.fire", ["desk" => ["x"]])), $k(fn () => officeStaffAction("office.hire", ["desks" => [["x"]]])),'
        . ' $k(fn () => officeStaffAction("office.hire", ["desks" => "snapshot"])), $w]);') . ' 2>&1');
    same('types: the web side refuses ?desk[]=y, {"a": [..]}, office.fire {"desk": ["x"]}, office.hire of non-strings — no warning',
        ['bad_request', 'bad_request', 'en', 'bad_request', 'bad_request', 'bad_request', []], json_decode((string) $web, true) ?? $web);
    $api = (string) file_get_contents(OFFICE_DIR . '/src/api.php');
    check('types: api.php reads its query and the action through apiText()', !preg_match('/\(string\) \(\$(_GET|data)\[/', $api));
}

/**
 * A desk that doesn't work here answers its look only (QA 2026-10-08, note 1: the agent switched an unhired watchman's
 * SIEM and whole-LAN watch on — only the web side checked): every other action of it is refused at the agent's
 * dispatch (not_hired) before its handler runs — the same rule as src/api.php's. Hired, the same requests reach their
 * handler (here: refused there for their payload — nothing is written); the Team Lead (always there) acts with any list.
 */
function testAgentHired(): void
{
    $staff = TESTS_RUN_DIR . '/hired-staff.json';
    $ask = fn (array $r): string => (string) (handle(json_encode($r))['error']['key'] ?? 'ok');
    $writes = [['action' => 'watchman.syslog_set', 'on' => 'x'], ['action' => 'watchman.net_lan_set', 'on' => 'x'],
               ['action' => 'watchman.notify_set', 'on' => 'x'], ['action' => 'watchman.posture_ack', 'id' => ['x']],
               ['action' => 'watchman.round'], ['action' => 'backup.schedule', 'cron' => [1]], ['action' => 'emby.schedule', 'job' => 'gather'],
               ['action' => 'snapshot.plan_toggle', 'id' => 'nosuch'], ['action' => 'snapshot.estimate', 'ids' => ['../x']],
               ['action' => 'restore.drill_set', 'x' => 1], ['action' => 'cleanup.measure', 'ids' => []]];
    $refusedThere = ['bad_request', 'bad_request', 'bad_request', 'bad_request', 'not_hired', 'bad_request', 'bad_request', 'bad_request',
                     'bad_request', 'bad_request', 'no_selection'];
    foreach (['no list' => null, 'an empty list' => ['hired' => []], 'others hired' => ['hired' => ['logs' => 1, 'advisor' => 2]]] as $what => $list) {
        @unlink($staff);
        if ($list !== null) {
            file_put_contents($staff, json_encode($list));
        }
        $GLOBALS['agentStaffFile'] = $staff;
        same("hired: $what — a desk's switches, schedules, settings and plans refused (not_hired)", array_fill(0, count($writes), 'not_hired'),
            array_map($ask, $writes));
        same("hired: $what — its look stays open (refresh), the Team Lead acts", [true, true, true, 'missing_field'],
            [agentDeskMayAct('watchman', 'refresh'), agentDeskMayAct('snapshot', 'refresh'), agentDeskMayAct('caretaker', 'menu_name'),
             $ask(['action' => 'caretaker.menu_name', 'name' => 'Office'])]);
    }
    file_put_contents($staff, json_encode(['hired' => ['watchman' => 1, 'backup' => 2, 'emby' => 3, 'snapshot' => 4, 'restore' => 5, 'whereabouts' => 6]]));
    $GLOBALS['agentStaffFile'] = $staff;
    $answers = array_map($ask, $writes);
    // watchman.round: hired in the list here, but his own check reads the live list — refused there, not at the dispatch
    same('hired: hired — the same requests reach their handlers (Ms. Whereabouts\' hiring counts for Ms. Dustdevil)', $refusedThere, $answers);
    same('hired: an unknown action of an unhired desk is still unknown_action', 'unknown_action', $ask(['action' => 'logs.nosuch']));
    file_put_contents($staff, json_encode(['hired' => ['backup' => 1]]));
    same('hired: one desk hired — the others still refused', ['not_hired', 'bad_request'],
        [$ask(['action' => 'watchman.syslog_set', 'on' => 'x']), $ask(['action' => 'backup.schedule', 'cron' => [1]])]);
    unset($GLOBALS['agentStaffFile']);
    @unlink($staff);
    $agent = (string) file_get_contents(OFFICE_DIR . '/agent/agent.php');
    check('hired: the dispatch asks before the handler', ($g = strpos($agent, "!agentDeskMayAct(\$deskId, \$action)")) !== false
        && $g < strpos($agent, 'return $handler($request);'));
}

/** For testRequestTypes(): a warning raised under `@` */
function agentPhpErrorSilenced(callable $log): void
{
    agentPhpError(E_WARNING, 'silenced', '/x/y.php', 1, $log, 5000);
}

/**
 * «Report a problem or a wish…» (agent/lib/report.php): the scrubber over crafted lines — paths (a film with spaces),
 * shares, pools, the server's and partners' names, users, addresses (IPv4, IPv6), MACs, mails, tokens, URLs with a
 * password, known secrets (one split by a control character) — nothing of them survives, and scrubbing twice is once;
 * the label map complete for every desk and every logLine() a desk writes; the desk's lines from agent.log; the preview's
 * parts, its token in RAM (0600) and no request; the report ID; the weekly pre-check; one send per token; the send
 * against a stand-in inbox (php -S) with every answer the Worker may give (and none at all); reports.json's shape; the
 * strict readers; the .cfg override of the inbox's address.
 */
function testReport(): void
{
    $tmp = hardeningTmp('report');
    @mkdir("$tmp/shares");
    @mkdir("$tmp/pools");
    @mkdir("$tmp/partner");
    @mkdir("$tmp/office", 0700);
    @mkdir("$tmp/run", 0700);
    $guid = '0781-5583-3311-A1B2C3D4E5F6';
    file_put_contents("$tmp/var.ini", "regGUID=\"$guid\"\nflashGUID=\"0951-1666-4C02-ABCDEF012345\"\ncsrf_token=\"0123456789ABCDEF\"\n");
    file_put_contents("$tmp/ident.cfg", "NAME=\"Nostromo\"\n");
    foreach (['Media', 'Backups', 'Fotos Familie', 'appdata', 'system'] as $s) {
        touch("$tmp/shares/$s.cfg");
    }
    foreach (['cache', 'hive'] as $p) {
        touch("$tmp/pools/$p.cfg");
    }
    file_put_contents("$tmp/passwd", "root:x:0:0::/root:/bin/bash\nnobody:x:99:100::/:/bin/false\nbenj:x:1000:100::/:/bin/false\n");
    $sshKey = 'ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIHkz9nq1Wc1o2Fv7Kp0Qm3yXcT5bLr8dE4uS6aJ0hN2i uso-partner:p1';
    file_put_contents("$tmp/partner/pairs.json", json_encode(['v' => 1, 'pairs' => [['id' => 'p1', 'name' => 'Tower', 'address' => 'tower.lan', 'my_key' => $sshKey]]]));
    file_put_contents("$tmp/emby.json", json_encode(['instances' => [['url' => 'http://10.0.0.5:8096', 'api_key' => 'abcdef0123456789abcdef']]]));
    file_put_contents("$tmp/supporter.json", json_encode(['key' => 'USO1.eyJ2IjoxfQ.MEUCIQD-sig']));
    $ctx = ['var_ini' => "$tmp/var.ini", 'ident' => "$tmp/ident.cfg", 'shares_dir' => "$tmp/shares", 'pools_dir' => "$tmp/pools", 'mounts' => ['/mnt/disk1', '/mnt/user', '/mnt/hive'],
            'passwd' => "$tmp/passwd", 'partner_dir' => "$tmp/partner", 'emby_settings' => "$tmp/emby.json", 'supporter' => "$tmp/supporter.json",
            'report_id_file' => "$tmp/office/report-id", 'hostname' => 'nostromo', 'reports' => "$tmp/office/reports.json", 'run_dir' => "$tmp/run",
            'hired' => ['caretaker', 'snapshot', 'backup'], 'unraid_version' => "$tmp/unraid-version", 'log' => "$tmp/agent.log"];
    file_put_contents("$tmp/unraid-version", "version=\"7.3.2\"\n");

    // the report ID: of its own, kept, never the tip page's server ID
    $id = reportId($ctx);
    same('report: the ID is sha256("uso-report:" + GUID)', hash('sha256', 'uso-report:' . strtoupper($guid)), $id);
    same('report: … kept in data/office/report-id, 0600', ["$id\n", '600'], [(string) @file_get_contents("$tmp/office/report-id"), decoct(fileperms("$tmp/office/report-id") & 0777)]);
    file_put_contents("$tmp/var2.ini", "regGUID=\"FFFF-0000-1111-222222222222\"\n");
    same('report: … made once (another GUID later keeps it)', $id, reportId(['var_ini' => "$tmp/var2.ini"] + $ctx));
    check('report: … unlinkable to the tip page\'s server ID', !str_contains(strtoupper($id), strtoupper(substr(hash('sha256', 'uso-supporter:' . strtoupper($guid)), 0, 16))));

    // the scrubber
    $know = reportKnow($ctx);
    same('report: shares and pools numbered by their names (Unraid\'s own shares kept)', [['Backups' => '‹share-1›', 'Fotos Familie' => '‹share-2›', 'Media' => '‹share-3›'], ['cache' => '‹pool-1›', 'hive' => '‹pool-2›']],
        [$know['shares'], $know['pools']]);
    $lines = [
        'moved /mnt/user/Media/My Film (2020)/My Film.mkv: done' => 'moved /mnt/user/‹share-3›/…: done',
        'copied to /mnt/hive/Media/My Film (2020)/My Film.mkv' => 'copied to /mnt/‹pool-2›/‹share-3›/…',
        'reads /mnt/user/appdata/UnraidSecretaryOffice/data/x.json' => 'reads /mnt/user/appdata/…',
        'reads "/mnt/disk1/Fotos Familie/2024/a.jpg", "/mnt/cache/Backups"' => 'reads "/mnt/disk1/‹share-2›/…", "/mnt/‹pool-1›/‹share-1›"',
        'at 10.0.0.5. Then 192.168.7.59:8096/x, [fe80::1] and fd00::1234:5678; not 17:02:11' => 'at …. Then …:8096/x, […] and …; not 17:02:11',
        'created hive/Media@uso-backup-20261008-0300, cache/Backups/sub@manual' => 'created ‹pool-2›/‹share-3›@uso-backup-20261008-0300, ‹pool-1›/‹share-1›/…@…',
        'Tower (tower.lan) answered from 192.168.7.59 and fd00::1234:5678 via 3c:7c:3f:12:34:56' => '‹partner-1› (‹partner-2›) answered from … and … via 3c:7c:3f:…',
        'mail benj@example.com from nostromo, user benj' => 'mail ‹mail› from ‹server›, user ‹user-1›',
        'token ghp_0123456789abcdefABCDEF0123456789abcd and api_key=hunter2' => 'token … and api_key=…',
        'GET https://admin:hunter2@nas.example.org:8443/api?key=x and https://github.com/dropnook/x' => 'GET https://‹host›/… and https://github.com/…',
        "key abcdef01\x0123456789abcdef in a line, csrf 0123456789ABCDEF, GUID $guid" => 'key ••• in a line, csrf •••, GUID •••',
        'the share Media is missing; Backups too; pool hive asleep' => 'the share ‹share-3› is missing; ‹share-1› too; pool ‹pool-2› asleep',
        'backup.sh ran on Nostromo, ' . $sshKey => 'backup.sh ran on ‹server›, •••',
        'cleared /boot/config/plugins/dynamix.my.servers/x.cfg: ok' => 'cleared /boot/config/plugins/dynamix.my.servers/…: ok',
        'cleared /tmp/secret/stuff: ok' => 'cleared <path>: ok',
        'kept /usr/local/emhttp/plugins/unraid-secretary-office/agent/agent.php' => 'kept /usr/local/emhttp/plugins/unraid-secretary-office/…',
        'disk "/mnt/remotes/NAS_films" and /mnt/addons/UnraidSecretaryOffice/metrics' => 'disk "/mnt/remotes/…" and /mnt/addons/UnraidSecretaryOffice/…',
        'id 123e4567-e89b-12d3-a456-426614174000 done' => 'id <uuid> done',
    ];
    $leaks = ['Media', 'Backups', 'Fotos', 'hive', 'Tower', 'tower.lan', '192.168', 'fd00', '12:34:56', 'benj', 'example', 'Nostromo', 'nostromo', 'ghp_', 'hunter2', 'admin',
              'abcdef0123', '0123456789ABCDEF', $guid, 'AAAAC3', 'NAS_films', '/tmp/secret', 'My Film', '426614174000'];
    foreach ($lines as $line => $want) {
        $seen = [];
        $got = reportScrub($line, $know, $seen);
        same('report: scrubbed — ' . mb_substr($line, 0, 50), $want, $got);
        foreach ($leaks as $l) {
            check("report: «{$l}» doesn't survive in «" . mb_substr($line, 0, 40) . '»', !str_contains($got, $l), $got);
        }
        same('report: scrubbing twice is once — ' . mb_substr($line, 0, 40), $got, reportScrub($got, $know));
    }
    $seen = [];
    reportScrub('the share Media on hive', $know, $seen);
    same('report: what was hidden, for the preview only', ['‹pool-2›' => 'hive', '‹share-3›' => 'Media'], (ksort($seen) ? $seen : $seen));
    same('report: a line is cut at 400 characters', 400, mb_strlen(reportScrub(str_repeat('word ', 200), $know)));
    same('report: Ms. Protocolli\'s comparing keeps its <path>', 'moved <path> to "<path>"', logsNormalizePaths('moved /mnt/user/Media/a.mkv to "/x/y z.mkv"'));

    // the label map: every desk, every logLine() of a desk starts with one of its labels
    same('report: a label for every desk (and the office)', [], array_values(array_diff(array_merge(['office'], array_keys(desks())), array_keys(REPORT_LOG_LABELS))));
    same('report: … and none for a desk that isn\'t', [], array_values(array_diff(array_keys(REPORT_LOG_LABELS), array_merge(['office'], array_keys(desks())))));
    $files = [];
    foreach (glob(OFFICE_DIR . '/agent/desks/*.php') ?: [] as $f) {
        $files[$f] = explode('-', basename($f, '.php'))[0];
    }
    foreach (['snapshotplans' => 'snapshot', 'where' => 'cleanup', 'partner' => 'caretaker', 'metrics' => 'office', 'house' => 'office', 'report' => 'office'] as $lib => $desk) {
        $files[OFFICE_DIR . "/agent/lib/$lib.php"] = $desk;
    }
    $files[OFFICE_DIR . '/agent/agent.php'] = 'office';
    // calls whose text isn't a literal — each looked at: Held:/Released: are labels; metricsNote()'s texts start
    // «Metrics:» (checked below); the agent's own with a variable in front are the office's anyway
    $notLiteral = ["(\$on ? 'Held: '", '$text', '$pinGone', '"$why', '"$dir'];
    $unlabelled = [];
    foreach ($files as $f => $desk) {
        $src = (string) file_get_contents($f);
        preg_match_all('/(?<![\w$>:])(?:logLine\(\s*(?:sprintf\(\s*)?|metricsNote\([^,()]+,\s*)(\'(?:\\\\.|[^\'\\\\])*\'|"(?:\\\\.|[^"\\\\])*"|[^\'")\s][^),]*)/', $src, $m);
        foreach ($m[1] as $arg) {
            if (str_starts_with($arg, 'string $text') || array_filter($notLiteral, fn ($x) => str_starts_with($arg, $x))) {
                continue;
            }
            $text = in_array($arg[0], ["'", '"'], true) ? stripcslashes(substr($arg, 1, -1)) : $arg;
            if (!preg_match('/^\$id: /', $text) && reportLabelOf($text, array_merge(REPORT_LOG_LABELS[$desk], $desk === 'office' ? [] : REPORT_LOG_OWN_LABELS)) === null) {
                $unlabelled[] = basename($f) . ': ' . mb_substr($text, 0, 50);
            }
        }
    }
    same('report: every logLine() a desk writes starts with one of its labels', [], $unlabelled);

    // the desk's lines from agent.log (and .1): its own, «<id>:», and the agent's start and errors
    file_put_contents("$tmp/agent.log.1", "2026-10-08 09:00:00  Agent started (v1.43.0, PID 1, desks: caretaker)\n2026-10-08 09:00:01  Ms. Snapshotini: plan p saved\n");
    file_put_contents("$tmp/agent.log", "2026-10-08 10:00:00  Backup: started backup.sh (run) via at\n"
        . "2026-10-08 10:00:01  Deleted: hive/Media@uso-plan-daily-20261001-0100\n"
        . "2026-10-08 10:00:02  snapshot: checks failed: /mnt/user/Media is gone\n"
        . "2026-10-08 10:00:03  Error: x (y.php:1)\n"
        . "2026-10-08 10:00:04  Ms. Snapshotini: created hive/Media@manual\n");
    same('report: the desk\'s lines in their order, from both files', ['2026-10-08 09:00:00  Agent started (v1.43.0, PID 1, desks: caretaker)', '2026-10-08 09:00:01  Ms. Snapshotini: plan p saved',
        '2026-10-08 10:00:01  Deleted: hive/Media@uso-plan-daily-20261001-0100', '2026-10-08 10:00:02  snapshot: checks failed: /mnt/user/Media is gone',
        '2026-10-08 10:00:03  Error: x (y.php:1)', '2026-10-08 10:00:04  Ms. Snapshotini: created hive/Media@manual'], reportLogLines('snapshot', 40, "$tmp/agent.log"));
    same('report: … at most n of the desk\'s', ['2026-10-08 10:00:03  Error: x (y.php:1)', '2026-10-08 10:00:04  Ms. Snapshotini: created hive/Media@manual'],
