    $GLOBALS['letgoHost']['scan'] = fn () => ['zfs' => ['snapshots' => []], 'btrfs' => ['snapshots' => []], 'vm' => ['snapshots' => []]];
    @unlink($args);
    $r2 = backupLetGoDo($place, false, $parts, $prefixes, '.btrfs-snap');
