        [$rT['moved'], $rT['failed_n'], $rT['failed'][0]['what'] ?? null, $rT['failed'][0]['key'] ?? null, $rT['failed'][0]['params']['detail'] ?? null,
         is_dir("$pool/apps/full"), is_dir("$pool/apps/fine"), $snapsAsked, is_int($jT['finished'] ?? null)]);
