        backupLetGoTrashRoots(['disk2' => true], "$tmp/journals"));
    same('let go: no folder — none', [], backupLetGoTrashRoots([], "$tmp/none"));

    // the strings
    $en = json_decode((string) file_get_contents(OFFICE_WEB . '/desks/backup/lang/en.json'), true) ?: [];
