    unset($GLOBALS['letgoHost'], $GLOBALS['snapshotHost'], $GLOBALS['snapshotRecordFile'], $GLOBALS['letgoDir'], $GLOBALS['letgoUbData'], $GLOBALS['letgoJob'], $GLOBALS['letgoRunDir']);
